import { clamp } from 'shared/math/MathUtils.js';

export class CollisionSystem {
  constructor() {
    this.shieldHit = false;
  }

  /**
   * Check player projectile against all invader bounds.
   * Returns { hit: true, invader, index } or { hit: false }.
   */
  checkPlayerProjectile(projPos, invaderBounds, aliveInvaders, shieldErodeFn) {
    // Check against each invader
    for (let i = 0; i < invaderBounds.length; i++) {
      const b = invaderBounds[i];
      if (!b) continue;
      if (this._pointInAABB(projPos.x, projPos.y, b)) {
        return { hit: true, invader: aliveInvaders[i], index: i };
      }
    }
    return { hit: false };
  }

  /**
   * Check invader projectile against player bounds.
   */
  checkInvaderProjectile(projPos, playerBounds) {
    return this._pointInAABB(projPos.x, projPos.y, playerBounds);
  }

  /**
   * Check player projectile against mystery ship bounds.
   */
  checkMysteryShip(projPos, shipBounds) {
    if (!shipBounds) return false;
    return this._pointInAABB(projPos.x, projPos.y, shipBounds);
  }

  /**
   * Check if projectile hit any shield.
   */
  checkProjectileVsShields(projPos, shieldErodeFn) {
    this.shieldHit = false;
    shieldErodeFn(projPos, 0.4);
    // We always erode; the shield itself tracks if cells were destroyed
    // Game layer checks via shieldHit flag set by erode returning true
  }

  /**
   * Check if any invader has descended below threshold (body collision with player).
   */
  checkInvaderDescent(invaderBounds, playerBounds) {
    for (const b of invaderBounds) {
      if (!b) continue;
      if (b.minY <= playerBounds.maxY && b.maxY >= playerBounds.minY) {
        if (b.maxX >= playerBounds.minX && b.minX <= playerBounds.maxX) {
          return true;
        }
      }
    }
    return false;
  }

  _pointInAABB(px, py, b) {
    return px >= b.minX && px <= b.maxX && py >= b.minY && py <= b.maxY;
  }
}

import * as THREE from 'three';
import { Player } from './Player.js';
import { InvaderGrid } from './InvaderGrid.js';
import { Shields } from './Shields.js';
import { ProjectileSystem } from './ProjectileSystem.js';
import { MysteryShip } from './MysteryShip.js';
import { WaveManager } from './WaveManager.js';
import { ScoreSystem } from './ScoreSystem.js';
import { CollisionSystem } from './CollisionSystem.js';
import { Background } from './Background.js';
import { HUD } from './HUD.js';
import { MemoryTracker } from 'shared/memory/MemoryTracker.js';
import { CONFIG } from './config.js';

export class Game {
  constructor(scene, camera, composer, input, vfx, audio) {
    this.scene = scene;
    this.camera = camera;
    this.composer = composer;
    this.input = input;
    this.vfx = vfx;
    this.audio = audio;

    this.tracker = new MemoryTracker();
    this.state = 'menu';
    this.waveClearTimer = 0;
    this.gameOverTimer = 0;

    // Subsystems
    this.player = null;
    this.invaderGrid = null;
    this.shields = null;
    this.projectiles = null;
    this.mysteryShip = null;
    this.waveManager = null;
    this.scoreSystem = null;
    this.collisions = null;
    this.background = null;
    this.hud = null;

    // Lighting
    this.orbitLight1 = null;
    this.orbitLight2 = null;
    this.playerLight = null;
    this.flashLight = null;
    this.orbitAngle = 0;

    // Screen flash
    this.flashOverlay = null;
    this.flashAlpha = 0;

    // Thruster timer
    this.thrusterTimer = 0;
  }

  init() {
    // Clear scene
    while (this.scene.children.length > 0) {
      this.scene.remove(this.scene.children[0]);
    }
    this.tracker.disposeAll();

    // Ambient light
    const ambient = new THREE.AmbientLight(0x334455, 0.4);
    this.scene.add(ambient);

    // Orbiting lights
    this.orbitLight1 = new THREE.PointLight(0x00ffff, 2, 30);
    this.orbitLight1.position.set(5, 5, 5);
    this.scene.add(this.orbitLight1);

    this.orbitLight2 = new THREE.PointLight(0xff00ff, 2, 30);
    this.orbitLight2.position.set(-5, -5, 5);
    this.scene.add(this.orbitLight2);

    // Player attached light
    this.playerLight = new THREE.PointLight(0x0088ff, 1.5, 8);
    this.scene.add(this.playerLight);

    // Flash light for explosions
    this.flashLight = new THREE.PointLight(0xffffff, 0, 20);
    this.scene.add(this.flashLight);

    // Screen flash overlay
    this.flashOverlay = document.getElementById('screen-flash');
    this.flashAlpha = 0;

    // Background
    this.background = new Background(this.scene, this.tracker);
    this.background.init();

    // Player
    this.player = new Player(this.scene, this.tracker);
    this.player.init();

    // Invader grid
    this.invaderGrid = new InvaderGrid(this.scene, this.tracker);
    this.invaderGrid.init(1);

    // Shields
    this.shields = new Shields(this.scene, this.tracker);
    this.shields.init();

    // Projectiles
    this.projectiles = new ProjectileSystem(this.scene, this.tracker);
    this.projectiles.init();

    // Mystery ship
    this.mysteryShip = new MysteryShip(this.scene, this.tracker);
    this.mysteryShip.init();

    // Wave manager
    this.waveManager = new WaveManager();

    // Score system
    this.scoreSystem = new ScoreSystem();

    // Collision system
    this.collisions = new CollisionSystem();

    // HUD
    this.hud = new HUD();
    this.hud.init();

    // Start music
    this.audio.startMusic();

    this.state = 'playing';
  }

  startWave(waveNum) {
    this.invaderGrid.reset(waveNum);
    this.shields.reset();
    this.projectiles.clear();
    this.mysteryShip.despawn();
    this.waveManager.advanceWave();
    this.scoreSystem.onWaveClear();
    this.audio.setWave(waveNum);
  }

  update(dt) {
    if (this.state === 'menu') {
      if (this.input.wasJustPressed('fire')) {
        this.init();
      }
      return;
    }

    if (this.state === 'gameOver') {
      this.gameOverTimer += dt;
      this.vfx.particles.update(dt);
      this.vfx.shockwaves.update(dt);
      this.vfx.floatingText.update(dt);
      this.background.update(dt);
      this.updateOrbitLights(dt);
      if (this.input.wasJustPressed('fire') && this.gameOverTimer > 2) {
        this.gameOverTimer = 0;
        this.init();
      }
      return;
    }

    if (this.state === 'waveClear') {
      this.waveClearTimer += dt;
      this.vfx.particles.update(dt);
      this.vfx.shockwaves.update(dt);
      this.vfx.floatingText.update(dt);
      this.background.update(dt);
      this.updateOrbitLights(dt);
      if (this.waveClearTimer > 3) {
        this.state = 'playing';
        this.startWave(this.waveManager.getWave() + 1);
      }
      return;
    }

    // Hit-stop check
    const timescale = this.vfx.hitStop.getTimescale();
    const gameDt = dt * timescale;

    // Update orbiting lights
    this.updateOrbitLights(dt);

    // Player light follows ship
    this.playerLight.position.copy(this.player.mesh.position);
    this.playerLight.position.z += 2;

    // Player update
    this.player.update(gameDt, this.input);

    // Thruster particles
    this.thrusterTimer += dt;
    if (this.thrusterTimer > 0.05) {
      this.thrusterTimer = 0;
      const count = Math.abs(this.input.getAxis('horizontal')) > 0.1 ? 3 : 1;
      this.vfx.particles.burst(
        this.player.mesh.position.clone(),
        count,
        0x0088ff,
        0.3,
        1.5
      );
    }

    // Invader grid update
    this.invaderGrid.update(gameDt);

    // Invader firing
    this.invaderGrid.fire(gameDt);

    // Projectile update
    this.projectiles.update(gameDt);

    // Mystery ship update
    this.mysteryShip.update(gameDt);

    // Collision detection
    this.resolveCollisions();

    // Check wave clear
    if (this.invaderGrid.getAlive().length === 0 && this.state === 'playing') {
      this.onWaveClear();
    }

    // Check invader descent
    if (this.invaderGrid.checkDescent() && this.state === 'playing') {
      this.onGameOver();
    }

    // Update HUD
    this.hud.update(
      this.scoreSystem.getScore(),
      this.waveManager.getWave(),
      this.player.hp,
      CONFIG.PLAYER_MAX_HP,
      this.scoreSystem.getCombo(),
      this.scoreSystem.getMultiplier()
    );

    // Update VFX
    this.vfx.particles.update(dt);
    this.vfx.shake.update(dt, this.camera);
    this.vfx.trails.update(dt);
    this.vfx.shockwaves.update(dt);
    this.vfx.floatingText.update(dt);
    this.background.update(dt);

    // Screen flash decay
    if (this.flashAlpha > 0) {
      this.flashAlpha -= dt * 3;
      if (this.flashAlpha < 0) this.flashAlpha = 0;
      if (this.flashOverlay) {
        this.flashOverlay.style.opacity = this.flashAlpha;
      }
    }
  }

  updateOrbitLights(dt) {
    this.orbitAngle += dt * 0.3;
    const r = 10;
    this.orbitLight1.position.x = Math.cos(this.orbitAngle) * r;
    this.orbitLight1.position.y = Math.sin(this.orbitAngle * 0.7) * r * 0.5;
    this.orbitLight2.position.x = Math.cos(this.orbitAngle + Math.PI) * r;
    this.orbitLight2.position.y = Math.sin(this.orbitAngle * 0.7 + Math.PI) * r * 0.5;
  }

  resolveCollisions() {
    const playerProjPos = this.projectiles.getPlayerProjPos();
    const invaderProjPositions = this.projectiles.getInvaderProjPositions();
    const aliveInvaders = this.invaderGrid.getAlive();
    const invaderBounds = aliveInvaders.map(inv => inv.getBounds());

    // Shield erosion callback
    const shieldErode = (pos, radius) => {
      this.shields.erode(pos, radius);
    };

    // Player projectile vs invaders
    if (playerProjPos) {
      const hit = this.collisions.checkPlayerProjectile(
        playerProjPos,
        invaderBounds,
        aliveInvaders,
        shieldErode
      );
      if (hit) {
        this.onInvaderKilled(hit.invader, hit.index);
        this.projectiles.removePlayerProjectile();
      } else {
        // Check vs mystery ship
        if (this.mysteryShip.isAlive) {
          const msHit = this.collisions.checkMysteryShip(playerProjPos, this.mysteryShip.getBounds());
          if (msHit) {
            this.onMysteryShipKilled();
            this.projectiles.removePlayerProjectile();
          }
        }
      }

      // Player projectile vs shields
      this.collisions.checkProjectileVsShields(playerProjPos, shieldErode);
      if (this.collisions.shieldHit) {
        this.projectiles.removePlayerProjectile();
        this.collisions.shieldHit = false;
      }
    }

    // Invader projectiles vs player
    for (let i = invaderProjPositions.length - 1; i >= 0; i--) {
      const projPos = invaderProjPositions[i];
      // vs shields first
      this.collisions.checkProjectileVsShields(projPos, shieldErode);
      if (this.collisions.shieldHit) {
        this.projectiles.removeInvaderProjectile(i);
        this.collisions.shieldHit = false;
        continue;
      }
      // vs player
      if (this.collisions.checkInvaderProjectile(projPos, this.player.getBounds())) {
        this.onPlayerHit();
        this.projectiles.removeInvaderProjectile(i);
      }
    }

    // Player vs invaders (body collision)
    if (this.collisions.checkInvaderDescent(invaderBounds, this.player.getBounds())) {
      this.onPlayerHit();
    }
  }

  onInvaderKilled(invader, index) {
    const basePoints = invader.points;
    const waveMult = this.waveManager.getMultiplier();
    const comboMult = this.scoreSystem.onKill(performance.now());
    const totalPoints = basePoints * waveMult * comboMult;

    this.scoreSystem.add(totalPoints, comboMult);

    // VFX
    const pos = invader.mesh.position.clone();
    const color = invader.emissiveColor;

    // Hit-stop (light)
    this.vfx.hitStop.trigger(60);

    // Camera shake
    this.vfx.shake.addTrauma(0.3);

    // Flash light
    this.flashLight.position.copy(pos);
    this.flashLight.intensity = 5;
    setTimeout(() => { this.flashLight.intensity = 0; }, 100);

    // Particle burst
    this.vfx.particles.burst(pos, 30, color, 1.5, 4);

    // Shockwave ring
    this.vfx.shockwaves.emit(pos, 2.0, color, 0.6);

    // Floating score text
    this.vfx.floatingText.show(pos, `+${totalPoints}`, color, 24, 1.2);

    // Audio
    this.audio.playSFX('invaderKill', 1.0 + (5 - invader.row) * 0.15);

    // Remove invader
    invader.die();
  }

  onPlayerHit() {
    this.player.takeDamage();

    // VFX
    const pos = this.player.mesh.position.clone();

    // Hit-stop (heavy)
    this.vfx.hitStop.trigger(120);

    // Camera shake
    this.vfx.shake.addTrauma(0.8);

    // Particles
    this.vfx.particles.burst(pos, 20, 0xffffff, 0.8, 3);

    // Audio
    this.audio.playSFX('playerHit');

    // Flash player ship
    this.player.flashHit();

    // Check death
    if (this.player.hp <= 0) {
      this.onGameOver();
    }
  }

  onMysteryShipKilled() {
    const points = this.mysteryShip.points;
    const waveMult = this.waveManager.getMultiplier();
    const totalPoints = points * waveMult;

    this.scoreSystem.add(totalPoints, 1);

    const pos = this.mysteryShip.mesh.position.clone();

    // Hit-stop (dramatic)
    this.vfx.hitStop.trigger(200);

    // Camera shake (heavy)
    this.vfx.shake.addTrauma(1.5);

    // Screen flash
    this.flashAlpha = 0.6;

    // Particles
    this.vfx.particles.burst(pos, 80, 0xff00ff, 3, 6);

    // Shockwave rings (2 staggered)
    this.vfx.shockwaves.emit(pos, 4.0, 0xff00ff, 0.8);
    setTimeout(() => {
      this.vfx.shockwaves.emit(pos, 3.0, 0xffffff, 0.6);
    }, 100);

    // Floating text
    this.vfx.floatingText.show(pos, `+${totalPoints}`, 0xffd700, 36, 2);

    // Audio
    this.audio.playSFX('mysteryKill');

    // Despawn
    this.mysteryShip.despawn();
  }

  onWaveClear() {
    this.state = 'waveClear';
    this.waveClearTimer = 0;

    // VFX
    this.vfx.hitStop.trigger(300);
    this.vfx.shake.addTrauma(0.5);

    // Celebration particles
    for (let i = 0; i < 5; i++) {
      const x = (Math.random() - 0.5) * 10;
      const y = (Math.random() - 0.5) * 6;
      const z = 0;
      const color = [0xff0000, 0x00ff00, 0x0000ff, 0xffff00, 0xff00ff][i];
      this.vfx.particles.burst(new THREE.Vector3(x, y, z), 20, color, 2, 5);
    }

    // Floating text
    this.vfx.floatingText.show(
      new THREE.Vector3(0, 2, 0),
      `WAVE ${this.waveManager.getWave()} COMPLETE`,
      0xffd700,
      32,
      2.5
    );

    // HUD
    this.hud.showWaveComplete(this.waveManager.getWave());

    // Audio
    this.audio.playSFX('waveClear');
  }

  onGameOver() {
    this.state = 'gameOver';
    this.gameOverTimer = 0;

    // Audio
    this.audio.playSFX('gameOver');
    this.audio.stopMusic();

    // VFX
    this.vfx.hitStop.trigger(400);
    this.vfx.shake.addTrauma(1.2);

    // Big explosion at player position
    this.vfx.particles.burst(
      this.player.mesh.position.clone(),
      60,
      0xff4444,
      2,
      5
    );

    // HUD
    const stats = {
      score: this.scoreSystem.getScore(),
      wave: this.waveManager.getWave(),
      invadersKilled: this.waveManager.getTotalKilled(),
      accuracy: 0 // simplified
    };
    this.hud.showGameOver(stats);
  }

  dispose() {
    this.tracker.disposeAll();
    if (this.hud) this.hud.dispose();
    this.audio.stopMusic();
  }
}

import { Shield } from './Shield.js';
import { CONFIG } from './config.js';

const SHIELD_POSITIONS = [
  { x: -4.5, y: -2.5 },
  { x: -1.5, y: -2.5 },
  { x:  1.5, y: -2.5 },
  { x:  4.5, y: -2.5 },
];

export class Shields {
  constructor(scene, tracker) {
    this.scene = scene;
    this.tracker = tracker;
    this.shields = [];
  }

  init() {
    this._createAll();
  }

  _createAll() {
    for (const s of this.shields) s.dispose();
    this.shields = [];
    for (const pos of SHIELD_POSITIONS) {
      this.shields.push(new Shield(this.scene, this.tracker, pos.x, pos.y));
    }
  }

  erode(point, radius) {
    for (const shield of this.shields) {
      if (shield.isAlive()) {
        shield.erode(point.x, point.y, radius);
      }
    }
  }

  reset() {
    this._createAll();
  }

  dispose() {
    for (const shield of this.shields) shield.dispose();
    this.shields = [];
  }
}

import * as THREE from 'three';
import { CONFIG } from './config.js';

export class ProjectileSystem {
  constructor(scene, tracker) {
    this.scene = scene;
    this.tracker = tracker;
    this.playerProjectiles = [];
    this.invaderProjectiles = [];
    this._playerGeo = null;
    this._playerMat = null;
    this._invaderGeo = null;
    this._invaderMat = null;
  }

  init() {
    this._playerGeo = new THREE.BoxGeometry(0.1, 0.4, 0.1);
    this.tracker.trackGeometry(this._playerGeo);
    this._playerMat = new THREE.MeshStandardMaterial({
      color: 0x00ffff, emissive: 0x00ffff, emissiveIntensity: 2.0,
      metalness: 0.3, roughness: 0.1,
    });
    this.tracker.trackMaterial(this._playerMat);

    this._invaderGeo = new THREE.BoxGeometry(0.12, 0.35, 0.12);
    this.tracker.trackGeometry(this._invaderGeo);
    this._invaderMat = new THREE.MeshStandardMaterial({
      color: 0xff4444, emissive: 0xff0000, emissiveIntensity: 1.5,
      metalness: 0.3, roughness: 0.1,
    });
    this.tracker.trackMaterial(this._invaderMat);
  }

  firePlayer(pos) {
    if (this.playerProjectiles.length >= 1) return;
    const mesh = new THREE.Mesh(this._playerGeo, this._playerMat);
    mesh.position.set(pos.x, pos.y, 0);
    this.scene.add(mesh);
    this.playerProjectiles.push(mesh);
  }

  fireInvader(pos) {
    if (this.invaderProjectiles.length >= CONFIG.INVADER_MAX_PROJECTILES) return;
    const mesh = new THREE.Mesh(this._invaderGeo, this._invaderMat);
    mesh.position.set(pos.x, pos.y, 0);
    this.scene.add(mesh);
    this.invaderProjectiles.push(mesh);
  }

  update(dt) {
    for (let i = this.playerProjectiles.length - 1; i >= 0; i--) {
      const p = this.playerProjectiles[i];
      p.position.y += CONFIG.PLAYER_PROJECTILE_SPEED * dt;
      if (p.position.y > 10) {
        this.scene.remove(p);
        this.playerProjectiles.splice(i, 1);
      }
    }
    for (let i = this.invaderProjectiles.length - 1; i >= 0; i--) {
      const p = this.invaderProjectiles[i];
      p.position.y -= CONFIG.INVADER_PROJECTILE_SPEED * dt;
      if (p.position.y < -10) {
        this.scene.remove(p);
        this.invaderProjectiles.splice(i, 1);
      }
    }
  }

  getPlayerProjPos() {
    if (this.playerProjectiles.length === 0) return null;
    return this.playerProjectiles[0].position.clone();
  }

  getInvaderProjPositions() {
    return this.invaderProjectiles.map(p => p.position.clone());
  }

  removePlayerProjectile() {
    if (this.playerProjectiles.length > 0) {
      const p = this.playerProjectiles.shift();
      this.scene.remove(p);
    }
  }

  removeInvaderProjectile(index) {
    if (index >= 0 && index < this.invaderProjectiles.length) {
      const p = this.invaderProjectiles.splice(index, 1)[0];
      this.scene.remove(p);
    }
  }

  clear() {
    for (const p of this.playerProjectiles) this.scene.remove(p);
    this.playerProjectiles.length = 0;
    for (const p of this.invaderProjectiles) this.scene.remove(p);
    this.invaderProjectiles.length = 0;
  }

  dispose() {
    this.clear();
  }
}

import * as THREE from 'three';
import { SimplexNoise } from 'shared/math/SimplexNoise.js';
import { randRange } from 'shared/math/MathUtils.js';
import { CONFIG } from './config.js';

const noise = new SimplexNoise(42);
const MYSTERY_COLORS = [0xff00ff, 0xff6600, 0x00ffff];
const MYSTERY_POINTS = [100, 300, 500];

export class MysteryShip {
  constructor(scene, tracker) {
    this.scene = scene;
    this.tracker = tracker;
    this.isAlive = false;
    this.points = 100;
    this.spawnTimer = 0;
    this.nextSpawnTime = randRange(CONFIG.MYSTERY_SHIP_MIN_INTERVAL, CONFIG.MYSTERY_SHIP_MAX_INTERVAL);
    this.halfW = 0.7;
    this.halfH = 0.35;
    this._built = false;
  }

  init() {
    if (this._built) return;
    this._built = true;

    const geo = new THREE.BoxGeometry(1.4, 0.5, 0.8, 8, 4, 4);
    const pos = geo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
      const n = noise.noise2D(x * 1.5, z * 1.5) * 0.15;
      pos.setZ(i, z + n);
      if (y > 0) pos.setY(i, y + Math.abs(x) * 0.15);
    }
    geo.computeVertexNormals();
    this.tracker.trackGeometry(geo);

    this.material = new THREE.MeshStandardMaterial({
      color: MYSTERY_COLORS[0],
      emissive: MYSTERY_COLORS[0],
      emissiveIntensity: 1.8,
      metalness: 0.7,
      roughness: 0.2,
    });
    this.tracker.trackMaterial(this.material);

    this.mesh = new THREE.Mesh(geo, this.material);
    this.mesh.visible = false;
    this.scene.add(this.mesh);

    const glowGeo = new THREE.SphereGeometry(0.3, 8, 8);
    this.tracker.trackGeometry(glowGeo);
    this.glowMat = new THREE.MeshStandardMaterial({
      color: 0xff00ff, emissive: 0xff00ff, emissiveIntensity: 3,
      transparent: true, opacity: 0.6,
    });
    this.tracker.trackMaterial(this.glowMat);
    this.glowMesh = new THREE.Mesh(glowGeo, this.glowMat);
    this.glowMesh.position.y = -0.4;
    this.mesh.add(this.glowMesh);

    this.light = new THREE.PointLight(0xff00ff, 2, 6);
    this.mesh.add(this.light);
  }

  getBounds() {
    return {
      minX: this.mesh.position.x - this.halfW,
      maxX: this.mesh.position.x + this.halfW,
      minY: this.mesh.position.y - this.halfH,
      maxY: this.mesh.position.y + this.halfH,
    };
  }

  spawn() {
    this.isAlive = true;
    const dir = Math.random() < 0.5 ? -1 : 1;
    this.mesh.position.set(
      dir > 0 ? -CONFIG.ARENA_WIDTH / 2 - 1 : CONFIG.ARENA_WIDTH / 2 + 1,
      CONFIG.MYSTERY_SHIP_Y,
      0
    );
    this._dir = dir;
    const ci = Math.floor(Math.random() * 3);
    this.points = MYSTERY_POINTS[ci];
    const color = MYSTERY_COLORS[ci];
    this.material.color.setHex(color);
    this.material.emissive.setHex(color);
    this.glowMat.color.setHex(color);
    this.glowMat.emissive.setHex(color);
    this.light.color.setHex(color);
    this.mesh.visible = true;
  }

  despawn() {
    this.isAlive = false;
    this.mesh.visible = false;
    this.spawnTimer = 0;
    this.nextSpawnTime = randRange(CONFIG.MYSTERY_SHIP_MIN_INTERVAL, CONFIG.MYSTERY_SHIP_MAX_INTERVAL);
  }

  update(dt) {
    if (!this.isAlive) {
      this.spawnTimer += dt;
      if (this.spawnTimer >= this.nextSpawnTime) this.spawn();
      return;
    }
    this.mesh.position.x += CONFIG.MYSTERY_SHIP_SPEED * this._dir * dt;
    this.mesh.position.z = Math.sin(performance.now() * 0.003) * 0.1;
    this.glowMesh.scale.setScalar(1 + Math.sin(performance.now() * 0.008) * 0.3);
    if (this.mesh.position.x < -CONFIG.ARENA_WIDTH / 2 - 2 ||
        this.mesh.position.x > CONFIG.ARENA_WIDTH / 2 + 2) {
      this.despawn();
    }
  }

  dispose() {
    this.scene.remove(this.mesh);
  }
}

export class HUD {
  constructor() {
    this._panel = document.getElementById('hud-panel');
    this._scoreEl = document.getElementById('hud-score');
    this._waveEl = document.getElementById('hud-wave');
    this._hpBar = document.getElementById('hud-hp-bar');
    this._comboEl = document.getElementById('hud-combo');
    this._multiplierEl = document.getElementById('hud-multiplier');
    this._overlay = document.getElementById('game-over-overlay');
    this._finalScore = document.getElementById('final-score');
    this._finalWave = document.getElementById('final-wave');
    this._finalKills = document.getElementById('final-kills');
    this._finalAccuracy = document.getElementById('final-accuracy');
    this._waveOverlay = document.getElementById('wave-overlay');
    this._waveText = document.getElementById('wave-text');
    this._startOverlay = document.getElementById('start-overlay');
    this._visible = true;
    this._maxHp = 3;
  }

  init() {
    // Build HP pips
    this._hpBar.innerHTML = '';
    for (let i = 0; i < this._maxHp; i++) {
      const pip = document.createElement('div');
      pip.className = 'hp-pip';
      this._hpBar.appendChild(pip);
    }
    this._pips = this._hpBar.querySelectorAll('.hp-pip');
    // Hide overlays
    this._overlay.classList.remove('visible');
    this._waveOverlay.classList.remove('visible');
  }

  update(score, wave, hp, maxHp, combo, multiplier) {
    if (!this._visible) return;
    this._scoreEl.textContent = score.toLocaleString();
    this._waveEl.textContent = `WAVE ${wave}`;
    // Update HP pips
    this._maxHp = maxHp;
    for (let i = 0; i < this._pips.length; i++) {
      if (i < hp) {
        this._pips[i].classList.remove('lost');
      } else {
        this._pips[i].classList.add('lost');
      }
    }
    if (multiplier > 1) {
      this._comboEl.style.display = 'block';
      this._comboEl.textContent = `COMBO ×${multiplier}`;
      this._comboEl.classList.add('active');
      this._multiplierEl.style.display = 'block';
      this._multiplierEl.textContent = `${combo}/${5}`;
    } else {
      this._comboEl.style.display = 'none';
      this._comboEl.classList.remove('active');
      this._multiplierEl.style.display = 'none';
    }
  }

  showGameOver(stats) {
    this._visible = false;
    this._panel.style.display = 'none';
    this._finalScore.textContent = stats.score.toLocaleString();
    this._finalWave.textContent = stats.wave;
    this._finalKills.textContent = stats.invadersKilled;
    this._finalAccuracy.textContent = `${stats.accuracy || 0}%`;
    this._overlay.classList.add('visible');
  }

  showWaveComplete(wave) {
    this._waveText.textContent = `WAVE ${wave} COMPLETE`;
    this._waveOverlay.classList.add('visible');
    setTimeout(() => { this._waveOverlay.classList.remove('visible'); }, 2500);
  }

  hide() { this._panel.style.display = 'none'; }

  dispose() {
    this._visible = false;
  }
}

import * as THREE from 'three';
import { randRange } from 'shared/math/MathUtils.js';
import { SimplexNoise } from 'shared/math/SimplexNoise.js';

export class Background {
  constructor(scene, tracker) {
    this.scene = scene;
    this.tracker = tracker;
    this.group = new THREE.Group();
    this.group.name = 'background';
    scene.add(this.group);
    this.starData = [];
  }

  init() {
    this._buildStarfield();
    this._buildGridFloor();
  }

  _buildStarfield() {
    const count = 2000;
    const geo = new THREE.SphereGeometry(0.03, 4, 4);
    this.tracker.trackGeometry(geo);
    const mat = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0x8888ff,
      emissiveIntensity: 0.5,
      roughness: 1,
      metalness: 0,
    });
    this.tracker.trackMaterial(mat);

    this.starMesh = new THREE.InstancedMesh(geo, mat, count);
    this.starMesh.name = 'starfield';
    const dummy = new THREE.Object3D();
    const noise = new SimplexNoise(42);

    for (let i = 0; i < count; i++) {
      const x = (Math.random() - 0.5) * 40;
      const y = (Math.random() - 0.5) * 30;
      const z = -Math.random() * 30 - 2;
      dummy.position.set(x, y, z);
      const scale = randRange(0.5, 2.0);
      dummy.scale.set(scale, scale, scale);
      dummy.updateMatrix();
      this.starMesh.setMatrixAt(i, dummy.matrix);
      this.starData.push({
        baseX: x, baseY: y, baseZ: z,
        twinkleSpeed: randRange(0.5, 3.0),
        twinklePhase: Math.random() * Math.PI * 2,
      });
    }
    this.starMesh.instanceMatrix.needsUpdate = true;
    this.group.add(this.starMesh);
  }

  _buildGridFloor() {
    const geo = new THREE.PlaneGeometry(60, 60);
    this.tracker.trackGeometry(geo);
    const mat = new THREE.MeshStandardMaterial({
      color: 0x001122,
      emissive: 0x002244,
      emissiveIntensity: 0.3,
      roughness: 0.9,
      metalness: 0.1,
      transparent: true,
      opacity: 0.4,
      side: THREE.DoubleSide,
    });
    this.tracker.trackMaterial(mat);
    const plane = new THREE.Mesh(geo, mat);
    plane.position.set(0, -7, -5);
    plane.rotation.x = -Math.PI / 2;
    plane.name = 'gridFloor';
    this.group.add(plane);
  }

  update(dt) {
    const time = performance.now() * 0.001;
    const dummy = new THREE.Object3D();
    for (let i = 0; i < this.starData.length; i++) {
      const s = this.starData[i];
      const twinkle = 0.5 + 0.5 * Math.sin(time * s.twinkleSpeed + s.twinklePhase);
      dummy.position.set(s.baseX, s.baseY, s.baseZ);
      const baseScale = 0.5 + twinkle * 1.5;
      dummy.scale.set(baseScale, baseScale, baseScale);
      dummy.updateMatrix();
      this.starMesh.setMatrixAt(i, dummy.matrix);
    }
    this.starMesh.instanceMatrix.needsUpdate = true;
  }

  dispose() {
    this.scene.remove(this.group);
  }
}

import * as THREE from 'three';
import { clamp } from 'shared/math/MathUtils.js';
import { SimplexNoise } from 'shared/math/SimplexNoise.js';
import { CONFIG } from './config.js';

export class Player {
  constructor(scene, tracker) {
    this.scene = scene;
    this.tracker = tracker;
    this.group = new THREE.Group();
    this.group.position.set(0, CONFIG.PLAYER_Y, 0);
    this.velocity = 0;
    this.hp = CONFIG.PLAYER_MAX_HP;
    this.fireCooldown = 0;
    this.invulnerable = 0;
    this.flashTimer = 0;
    this.alive = true;
    this.halfW = 0.6;
    this.halfH = 0.35;
    this.mesh = null;
    this.material = null;
    this.thruster = null;
    this.thrusterMat = null;
  }

  init() {
    const geo = new THREE.BoxGeometry(1.2, 0.5, 0.8, 8, 4, 4);
    const pos = geo.attributes.position;
    const noise = new SimplexNoise(42);
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
      const n = noise.noise3D(x * 2, y * 2, z * 2) * 0.08;
      const taper = y > 0 ? 1 - y * 0.5 : 1 + y * 0.2;
      pos.setX(i, x * taper + n);
      pos.setZ(i, z * taper + n);
      if (y > 0.15) pos.setY(i, y + 0.15);
    }
    geo.computeVertexNormals();
    this.tracker.trackGeometry(geo);

    this.material = new THREE.MeshStandardMaterial({
      color: 0x00ffff, emissive: 0x0088ff, emissiveIntensity: 1.2,
      metalness: 0.8, roughness: 0.2,
    });
    this.tracker.trackMaterial(this.material);

    this.mesh = new THREE.Mesh(geo, this.material);
    this.group.add(this.mesh);

    const thrusterGeo = new THREE.SphereGeometry(0.15, 8, 8);
    this.tracker.trackGeometry(thrusterGeo);
    this.thrusterMat = new THREE.MeshStandardMaterial({
      color: 0x00ccff, emissive: 0x00aaff, emissiveIntensity: 2.0,
      transparent: true, opacity: 0.8,
    });
    this.tracker.trackMaterial(this.thrusterMat);
    this.thruster = new THREE.Mesh(thrusterGeo, this.thrusterMat);
    this.thruster.position.set(0, -0.35, 0);
    this.group.add(this.thruster);

    this.scene.add(this.group);
  }

  getBounds() {
    return {
      minX: this.group.position.x - this.halfW,
      maxX: this.group.position.x + this.halfW,
      minY: this.group.position.y - this.halfH,
      maxY: this.group.position.y + this.halfH,
    };
  }

  update(dt, input) {
    if (!this.alive) return;
    if (this.invulnerable > 0) {
      this.invulnerable -= dt;
      this.mesh.visible = Math.floor(this.invulnerable * 10) % 2 === 0;
    } else {
      this.mesh.visible = true;
    }
    if (this.flashTimer > 0) {
      this.flashTimer -= dt;
      this.material.emissive.setHex(0xffffff);
      this.material.emissiveIntensity = 3.0;
    } else {
      this.material.emissive.setHex(0x0088ff);
      this.material.emissiveIntensity = 1.2;
    }
    const axis = input.getAxis('horizontal');
    if (Math.abs(axis) > 0.1) {
      this.velocity += axis * CONFIG.PLAYER_ACCEL * dt;
    } else {
      if (this.velocity > 0) this.velocity = Math.max(0, this.velocity - CONFIG.PLAYER_DECEL * dt);
      else if (this.velocity < 0) this.velocity = Math.min(0, this.velocity + CONFIG.PLAYER_DECEL * dt);
    }
    this.velocity = clamp(this.velocity, -CONFIG.PLAYER_MAX_SPEED, CONFIG.PLAYER_MAX_SPEED);
    this.group.position.x += this.velocity * dt;
    this.group.position.x = clamp(
      this.group.position.x,
      -CONFIG.ARENA_WIDTH / 2 + this.halfW,
      CONFIG.ARENA_WIDTH / 2 - this.halfW
    );
    const thrustScale = 1 + Math.abs(this.velocity) * 0.05 + Math.sin(performance.now() * 0.01) * 0.1;
    this.thruster.scale.setScalar(thrustScale);
    this.thrusterMat.emissiveIntensity = 1.5 + Math.abs(this.velocity) * 0.15;
    if (this.fireCooldown > 0) this.fireCooldown -= dt;
  }

  fire() {
    if (this.fireCooldown > 0 || !this.alive) return null;
    this.fireCooldown = CONFIG.PLAYER_FIRE_COOLDOWN;
    return { x: this.group.position.x, y: this.group.position.y + this.halfH + 0.1, z: 0 };
  }

  takeDamage() {
    if (this.invulnerable > 0 || !this.alive) return false;
    this.hp--;
    this.flashTimer = 0.15;
    this.invulnerable = 1.0;
    if (this.hp <= 0) {
      this.alive = false;
      this.mesh.visible = false;
      this.thruster.visible = false;
    }
    return true;
  }

  flashHit() {
    this.flashTimer = 0.15;
  }

  reset() {
    this.hp = CONFIG.PLAYER_MAX_HP;
    this.alive = true;
    this.velocity = 0;
    this.fireCooldown = 0;
    this.invulnerable = 0;
    this.flashTimer = 0;
    this.group.position.set(0, CONFIG.PLAYER_Y, 0);
    this.mesh.visible = true;
    this.thruster.visible = true;
    this.material.emissive.setHex(0x0088ff);
    this.material.emissiveIntensity = 1.2;
  }

  dispose() {
    if (this.group.parent) this.group.parent.remove(this.group);
  }
}

import * as THREE from 'three';
import { SimplexNoise } from 'shared/math/SimplexNoise.js';
import { CONFIG } from './config.js';

const TYPE_COLORS = [
  { color: 0xff4444, emissive: 0xff0000, points: 50 },
  { color: 0xffaa00, emissive: 0xff6600, points: 40 },
  { color: 0xffaa00, emissive: 0xff6600, points: 40 },
  { color: 0x44ff44, emissive: 0x00ff00, points: 30 },
  { color: 0x44aaff, emissive: 0x0066ff, points: 10 },
];

export class Invader {
  constructor(scene, tracker, type, row, pos) {
    this.scene = scene;
    this.tracker = tracker;
    this.row = row;
    this.alive = true;
    this.legPhase = 0;
    this.flashTimer = 0;

    const tc = TYPE_COLORS[row] || TYPE_COLORS[0];
    this.points = tc.points;
    this.emissiveColor = tc.emissive;

    const size = row === 0 ? 0.55 : (row >= 3 ? 0.45 : 0.5);

    // Body
    const geo = new THREE.BoxGeometry(size, size * 0.8, size * 0.6, 4, 4, 4);
    const noise = new SimplexNoise(row * 100 + (pos?.x || 0));
    const posAttr = geo.attributes.position;
    for (let i = 0; i < posAttr.count; i++) {
      const x = posAttr.getX(i), y = posAttr.getY(i), z = posAttr.getZ(i);
      const n = noise.noise2D(x * 2, y * 2) * 0.08;
      posAttr.setXYZ(i, x + n, y + n * 0.5, z + n);
    }
    geo.computeVertexNormals();
    this.tracker.trackGeometry(geo);

    this._bodyMat = new THREE.MeshStandardMaterial({
      color: tc.color,
      emissive: tc.emissive,
      emissiveIntensity: 0.8,
      metalness: 0.6,
      roughness: 0.3,
    });
    this.tracker.trackMaterial(this._bodyMat);

    this._bodyMesh = new THREE.Mesh(geo, this._bodyMat);

    // Legs
    const legGeo = new THREE.BoxGeometry(0.12, 0.25, 0.12);
    this.tracker.trackGeometry(legGeo);
    const legMat = new THREE.MeshStandardMaterial({
      color: tc.color,
      emissive: tc.emissive,
      emissiveIntensity: 0.5,
      metalness: 0.4,
      roughness: 0.5,
    });
    this.tracker.trackMaterial(legMat);

    this._legL = new THREE.Mesh(legGeo, legMat);
    this._legL.position.set(-size * 0.45, -size * 0.5, 0);
    this._legR = new THREE.Mesh(legGeo, legMat);
    this._legR.position.set(size * 0.45, -size * 0.5, 0);

    this.mesh = new THREE.Group();
    this.mesh.add(this._bodyMesh);
    this.mesh.add(this._legL);
    this.mesh.add(this._legR);

    this._halfW = size * 0.7;
    this._halfH = size * 0.6;

    if (pos) this.mesh.position.set(pos.x, pos.y, pos.z || 0);
    scene.add(this.mesh);
  }

  getBounds() {
    return {
      minX: this.mesh.position.x - this._halfW,
      maxX: this.mesh.position.x + this._halfW,
      minY: this.mesh.position.y - this._halfH,
      maxY: this.mesh.position.y + this._halfH,
    };
  }

  animateLegs() {
    this.legPhase = this.legPhase ? 0 : 1;
    const angle = this.legPhase ? 0.4 : -0.4;
    this._legL.rotation.z = angle;
    this._legR.rotation.z = -angle;
    this._legL.position.y = -this._halfH * 1.1 + (this.legPhase ? 0.05 : -0.05);
    this._legR.position.y = -this._halfH * 1.1 + (this.legPhase ? -0.05 : 0.05);
  }

  flash() {
    this._bodyMat.emissive.setHex(0xffffff);
    this._bodyMat.emissiveIntensity = 3;
    this.flashTimer = 0.15;
  }

  updateFlash(dt) {
    if (this.flashTimer > 0) {
      this.flashTimer -= dt;
      if (this.flashTimer <= 0) {
        const tc = TYPE_COLORS[this.row] || TYPE_COLORS[0];
        this._bodyMat.emissive.setHex(tc.emissive);
        this._bodyMat.emissiveIntensity = 0.8;
      }
    }
  }

  die() {
    this.flash();
    this.alive = false;
    this.mesh.visible = false;
  }

  dispose() {
    if (this.mesh.parent) this.mesh.parent.remove(this.mesh);
  }
}

import * as THREE from 'three';
import { Invader } from './Invader.js';
import { clamp } from 'shared/math/MathUtils.js';
import { tracker } from 'shared/memory/MemoryTracker.js';
import { CONFIG } from './config.js';

export class InvaderGrid {
  constructor(scene, trackerRef) {
    this.scene = scene;
    this.tracker = trackerRef || tracker;
    this.group = new THREE.Group();
    this.scene.add(this.group);
    this.invaders = [];
    this.direction = 1;
    this.stepTimer = 0;
    this.stepInterval = 1.8;
    this.aliveCount = 0;
    this.waveNum = 1;
  }

  init(waveNum) {
    this.waveNum = waveNum;
    this._buildGrid();
  }

  reset(waveNum) {
    for (const inv of this.invaders) {
      this.group.remove(inv.mesh);
      inv.dispose();
    }
    this.invaders = [];
    this.aliveCount = 0;
    this.direction = 1;
    this.stepTimer = 0;
    this.waveNum = waveNum;
    this._buildGrid();
  }

  _buildGrid() {
    const { INVADER_ROWS, INVADER_COLS } = CONFIG;
    const spacingX = 0.9;
    const spacingY = 0.85;
    const startX = -((INVADER_COLS - 1) * spacingX) / 2;
    const startY = 4;

    for (let row = 0; row < INVADER_ROWS; row++) {
      for (let col = 0; col < INVADER_COLS; col++) {
        const x = startX + col * spacingX;
        const y = startY - row * spacingY;
        const invader = new Invader(this.scene, this.tracker, row, col, { x, y, z: 0 });
        this.group.add(invader.mesh);
        this.invaders.push(invader);
        this.aliveCount++;
      }
    }
    this.stepInterval = Math.max(0.08, 1.8 / this.aliveCount);
  }

  update(dt) {
    if (this.aliveCount <= 0) return;
    this.stepTimer += dt;
    if (this.stepTimer < this.stepInterval) return;
    this.stepTimer = 0;
    this._step();
  }

  _step() {
    const { INVADER_BOUNDARY_X, INVADER_STEP_DX, INVADER_STEP_DY } = CONFIG;
    let needDescent = false;

    for (const inv of this.invaders) {
      if (!inv.alive) continue;
      if (Math.abs(inv.mesh.position.x + INVADER_STEP_DX * this.direction) > INVADER_BOUNDARY_X) {
        needDescent = true;
        break;
      }
    }

    if (needDescent) {
      this.direction *= -1;
      for (const inv of this.invaders) {
        if (!inv.alive) continue;
        inv.mesh.position.y += INVADER_STEP_DY;
      }
    } else {
      for (const inv of this.invaders) {
        if (!inv.alive) continue;
        inv.mesh.position.x += INVADER_STEP_DX * this.direction;
        inv.animateLegs();
      }
    }

    this.stepInterval = Math.max(0.08, 1.8 / Math.max(1, this.aliveCount));
  }

  fire(dt) {
    if (this.aliveCount <= 0) return;
    const { INVADER_FIRE_PROB_BASE } = CONFIG;
    const prob = INVADER_FIRE_PROB_BASE * (56 - this.aliveCount) * (1 + (this.waveNum - 1) * 0.15);
    const aliveInvaders = this.invaders.filter(i => i.alive);
    if (aliveInvaders.length === 0) return;
    if (Math.random() < prob * dt * 60) {
      const invader = aliveInvaders[Math.floor(Math.random() * aliveInvaders.length)];
      return { x: invader.mesh.position.x, y: invader.mesh.position.y - 0.3, z: 0 };
    }
  }

  getAlive() {
    return this.invaders.filter(i => i.alive);
  }

  checkDescent() {
    const { INVADER_DEATH_Y } = CONFIG;
    for (const inv of this.invaders) {
      if (!inv.alive) continue;
      if (inv.mesh.position.y <= INVADER_DEATH_Y) return true;
    }
    return false;
  }

  dispose() {
    for (const inv of this.invaders) {
      this.group.remove(inv.mesh);
      inv.dispose();
    }
    this.invaders = [];
    this.scene.remove(this.group);
  }
}

import * as THREE from 'three';
import { CONFIG } from './config.js';

const { SHIELD_CELLS_X, SHIELD_CELLS_Y, SHIELD_EROSION_RADIUS } = CONFIG;
const CELL_W = 0.18;
const CELL_H = 0.18;
const TOTAL = SHIELD_CELLS_X * SHIELD_CELLS_Y;

export class Shield {
  constructor(scene, tracker, x, y) {
    this.scene = scene;
    this.tracker = tracker;
    this.baseX = x;
    this.baseY = y;
    this.alive = new Uint8Array(TOTAL).fill(1);
    this.aliveCount = TOTAL;

    const geo = new THREE.BoxGeometry(CELL_W, CELL_H, 0.15);
    this.tracker.trackGeometry(geo);
    const mat = new THREE.MeshStandardMaterial({
      color: 0x00ff88,
      emissive: 0x00ff44,
      emissiveIntensity: 0.6,
      transparent: true,
      opacity: 0.85,
      metalness: 0.2,
      roughness: 0.6,
    });
    this.tracker.trackMaterial(mat);

    this.mesh = new THREE.InstancedMesh(geo, mat, TOTAL);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this._dummy = new THREE.Object3D();
    this._updateInstances();
    this.mesh.instanceMatrix.needsUpdate = true;
    scene.add(this.mesh);
  }

  _idx(cx, cy) { return cy * SHIELD_CELLS_X + cx; }

  _cellWorld(cx, cy) {
    return {
      x: this.baseX + (cx - (SHIELD_CELLS_X - 1) / 2) * CELL_W,
      y: this.baseY + (cy - (SHIELD_CELLS_Y - 1) / 2) * CELL_H,
    };
  }

  _updateInstances() {
    let i = 0;
    for (let cy = 0; cy < SHIELD_CELLS_Y; cy++) {
      for (let cx = 0; cx < SHIELD_CELLS_X; cx++) {
        if (this.alive[this._idx(cx, cy)]) {
          const w = this._cellWorld(cx, cy);
          this._dummy.position.set(w.x, w.y, 0);
          this._dummy.scale.setScalar(1);
          this._dummy.updateMatrix();
          this.mesh.setMatrixAt(i, this._dummy.matrix);
        } else {
          this._dummy.position.set(0, 0, 0);
          this._dummy.scale.setScalar(0);
          this._dummy.updateMatrix();
          this.mesh.setMatrixAt(i, this._dummy.matrix);
        }
        i++;
      }
    }
  }

  erode(px, py, radius = SHIELD_EROSION_RADIUS) {
    const r2 = radius * radius;
    let changed = false;
    for (let cy = 0; cy < SHIELD_CELLS_Y; cy++) {
      for (let cx = 0; cx < SHIELD_CELLS_X; cx++) {
        const idx = this._idx(cx, cy);
        if (!this.alive[idx]) continue;
        const w = this._cellWorld(cx, cy);
        const dx = w.x - px;
        const dy = w.y - py;
        if (dx * dx + dy * dy < r2) {
          this.alive[idx] = 0;
          this.aliveCount--;
          changed = true;
        }
      }
    }
    if (changed) {
      this._updateInstances();
      this.mesh.instanceMatrix.needsUpdate = true;
    }
    return changed;
  }

  getBounds() {
    const hw = (SHIELD_CELLS_X * CELL_W) / 2;
    const hh = (SHIELD_CELLS_Y * CELL_H) / 2;
    return { minX: this.baseX - hw, maxX: this.baseX + hw, minY: this.baseY - hh, maxY: this.baseY + hh };
  }

  isAlive() { return this.aliveCount > 0; }

  reset() {
    this.alive.fill(1);
    this.aliveCount = TOTAL;
    this._updateInstances();
    this.mesh.instanceMatrix.needsUpdate = true;
  }

  dispose() {
    this.scene.remove(this.mesh);
    this.mesh.dispose();
  }
}

import * as THREE from 'three';
import { Game } from './Space_Invaders/Game.js';

let gameInstance = null;

async function boot() {
  await waitForAudio();

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.0;
  document.getElementById('canvas-container').appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050510);
  scene.fog = new THREE.FogExp2(0x050510, 0.015);

  const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 100);
  camera.position.set(0, 0, 14);
  camera.lookAt(0, 0, 0);

  const { createComposer } = await import('shared/rendering/EffectComposerSetup.js');
  const { composer } = createComposer(renderer, window.innerWidth, window.innerHeight, {
    strength: 0.6, radius: 0.4, threshold: 0.85,
  });

  const { InputManager } = await import('shared/input/InputManager.js');
  const { ParticleManager } = await import('shared/vfx/ParticleManager.js');
  const { CameraShake } = await import('shared/vfx/CameraShake.js');
  const { HitStop } = await import('shared/vfx/HitStop.js');
  const { MotionTrails } = await import('shared/vfx/MotionTrails.js');
  const { ShockwaveRings } = await import('shared/vfx/ShockwaveRings.js');
  const { FloatingText } = await import('shared/vfx/FloatingText.js');
  const { AudioManager } = await import('shared/audio/AudioManager.js');

  const input = new InputManager();
  const particles = new ParticleManager(scene, 500);
  const cameraShake = new CameraShake();
  const hitStop = new HitStop();
  const motionTrails = new MotionTrails(scene);
  const shockwaves = new ShockwaveRings(scene);
  const floatingText = new FloatingText(scene);
  const audio = new AudioManager();

  audio.init();
  audio.setVolume(0.3);

  gameInstance = new Game(scene, camera, composer, input, {
    particles,
    shake: cameraShake,
    hitStop,
    trails: motionTrails,
    shockwaves,
    floatingText,
  }, audio);

  gameInstance.init();

  window.addEventListener('resize', () => {
    const w = window.innerWidth, h = window.innerHeight;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
    composer.setSize(w, h);
  });

  const clock = new THREE.Clock();
  function loop() {
    requestAnimationFrame(loop);
    const rawDt = Math.min(clock.getDelta(), 0.05);
    input.update();
    hitStop.update();
    const timescale = hitStop.getTimescale();
    const dt = timescale > 0 ? rawDt : 0;
    gameInstance.update(dt, rawDt);
    cameraShake.update(rawDt, camera);
    particles.update(dt);
    motionTrails.update(dt);
    shockwaves.update(dt);
    floatingText.update(dt);
    composer.render();
  }
  loop();
}

function waitForAudio() {
  return new Promise((resolve) => {
    const el = document.getElementById('start-overlay');
    const btn = document.getElementById('btn-start');
    const handler = () => {
      el.removeEventListener('click', handler);
      el.removeEventListener('touchstart', handler);
      btn.removeEventListener('click', handler);
      el.style.opacity = '0';
      setTimeout(() => el.style.display = 'none', 500);
      resolve();
    };
    el.addEventListener('click', handler);
    el.addEventListener('touchstart', handler);
    btn.addEventListener('click', handler);
  });
}

boot();

import * as THREE from 'three';
import { Player } from './Player.js';
import { InvaderGrid } from './InvaderGrid.js';
import { Shields } from './Shields.js';
import { ProjectileSystem } from './ProjectileSystem.js';
import { MysteryShip } from './MysteryShip.js';
import { WaveManager } from './WaveManager.js';
import { ScoreSystem } from './ScoreSystem.js';
import { CollisionSystem } from './CollisionSystem.js';
import { Background } from './Background.js';
import { HUD } from './HUD.js';
import { MemoryTracker } from 'shared/memory/MemoryTracker.js';
import { CONFIG } from './config.js';

export class Game {
  constructor(scene, camera, composer, input, vfx, audio) {
    this.scene = scene;
    this.camera = camera;
    this.composer = composer;
    this.input = input;
    this.vfx = vfx;
    this.audio = audio;

    this.tracker = new MemoryTracker();
    this.state = 'menu';
    this.waveClearTimer = 0;
    this.gameOverTimer = 0;

    // Subsystems
    this.player = null;
    this.invaderGrid = null;
    this.shields = null;
    this.projectiles = null;
    this.mysteryShip = null;
    this.waveManager = null;
    this.scoreSystem = null;
    this.collisions = null;
    this.background = null;
    this.hud = null;

    // Lighting
    this.orbitLight1 = null;
    this.orbitLight2 = null;
    this.playerLight = null;
    this.flashLight = null;
    this.orbitAngle = 0;

    // Screen flash
    this.flashOverlay = null;
    this.flashAlpha = 0;

    // Thruster timer
    this.thrusterTimer = 0;
  }

  init() {
    // Clear scene
    while (this.scene.children.length > 0) {
      this.scene.remove(this.scene.children[0]);
    }
    this.tracker.disposeAll();

    // Ambient light
    const ambient = new THREE.AmbientLight(0x334455, 0.4);
    this.scene.add(ambient);

    // Orbiting lights
    this.orbitLight1 = new THREE.PointLight(0x00ffff, 2, 30);
    this.orbitLight1.position.set(5, 5, 5);
    this.scene.add(this.orbitLight1);

    this.orbitLight2 = new THREE.PointLight(0xff00ff, 2, 30);
    this.orbitLight2.position.set(-5, -5, 5);
    this.scene.add(this.orbitLight2);

    // Player attached light
    this.playerLight = new THREE.PointLight(0x0088ff, 1.5, 8);
    this.scene.add(this.playerLight);

    // Flash light for explosions
    this.flashLight = new THREE.PointLight(0xffffff, 0, 20);
    this.scene.add(this.flashLight);

    // Screen flash overlay
    this.flashOverlay = document.getElementById('screen-flash');
    this.flashAlpha = 0;

    // Background
    this.background = new Background(this.scene, this.tracker);
    this.background.init();

    // Player
    this.player = new Player(this.scene, this.tracker);
    this.player.init();

    // Invader grid
    this.invaderGrid = new InvaderGrid(this.scene, this.tracker);
    this.invaderGrid.init(1);

    // Shields
    this.shields = new Shields(this.scene, this.tracker);
    this.shields.init();

    // Projectiles
    this.projectiles = new ProjectileSystem(this.scene, this.tracker);
    this.projectiles.init();

    // Mystery ship
    this.mysteryShip = new MysteryShip(this.scene, this.tracker);
    this.mysteryShip.init();

    // Wave manager
    this.waveManager = new WaveManager();

    // Score system
    this.scoreSystem = new ScoreSystem();

    // Collision system
    this.collisions = new CollisionSystem();

    // HUD
    this.hud = new HUD();
    this.hud.init();

    // Start music
    this.audio.startMusic();

    this.state = 'playing';
  }

  startWave(waveNum) {
    this.invaderGrid.reset(waveNum);
    this.shields.reset();
    this.projectiles.clear();
    this.mysteryShip.despawn();
    this.waveManager.advanceWave();
    this.scoreSystem.onWaveClear();
    this.audio.setWave(waveNum);
  }

  update(dt) {
    if (this.state === 'menu') {
      if (this.input.wasJustPressed('fire')) {
        this.init();
      }
      return;
    }

    if (this.state === 'gameOver') {
      this.gameOverTimer += dt;
      this.vfx.particles.update(dt);
      this.vfx.shockwaves.update(dt);
      this.vfx.floatingText.update(dt);
      this.background.update(dt);
      this.updateOrbitLights(dt);
      if (this.input.wasJustPressed('fire') && this.gameOverTimer > 2) {
        this.gameOverTimer = 0;
        this.init();
      }
      return;
    }

    if (this.state === 'waveClear') {
      this.waveClearTimer += dt;
      this.vfx.particles.update(dt);
      this.vfx.shockwaves.update(dt);
      this.vfx.floatingText.update(dt);
      this.background.update(dt);
      this.updateOrbitLights(dt);
      if (this.waveClearTimer > 3) {
        this.state = 'playing';
        this.startWave(this.waveManager.getWave() + 1);
      }
      return;
    }

    // Hit-stop check
    const timescale = this.vfx.hitStop.getTimescale();
    const gameDt = dt * timescale;

    // Update orbiting lights
    this.updateOrbitLights(dt);

    // Player light follows ship
    this.playerLight.position.copy(this.player.group.position);
    this.playerLight.position.z += 2;

    // Player update
    this.player.update(gameDt, this.input);

    // Player firing
    const firePos = this.player.fire();
    if (firePos) {
      this.projectiles.firePlayer(firePos);
      this.audio.playSFX('playerShoot');
    }

    // Thruster particles
    this.thrusterTimer += dt;
    if (this.thrusterTimer > 0.05) {
      this.thrusterTimer = 0;
      const count = Math.abs(this.input.getAxis('horizontal')) > 0.1 ? 3 : 1;
      this.vfx.particles.burst(
        this.player.group.position.clone(),
        count,
        0x0088ff,
        0.3,
        1.5
      );
    }

    // Invader grid update
    this.invaderGrid.update(gameDt);

    // Invader firing
    const invaderFirePos = this.invaderGrid.fire(gameDt);
    if (invaderFirePos) {
      this.projectiles.fireInvader(invaderFirePos);
      this.audio.playSFX('invaderShoot');
    }

    // Projectile update
    this.projectiles.update(gameDt);

    // Mystery ship update
    this.mysteryShip.update(gameDt);

    // Collision detection
    this.resolveCollisions();

    // Check wave clear
    if (this.invaderGrid.getAlive().length === 0 && this.state === 'playing') {
      this.onWaveClear();
    }

    // Check invader descent
    if (this.invaderGrid.checkDescent() && this.state === 'playing') {
      this.onGameOver();
    }

    // Update HUD
    this.hud.update(
      this.scoreSystem.getScore(),
      this.waveManager.getWave(),
      this.player.hp,
      CONFIG.PLAYER_MAX_HP,
      this.scoreSystem.getCombo(),
      this.scoreSystem.getMultiplier()
    );

    // Update VFX
    this.vfx.particles.update(dt);
    this.vfx.shake.update(dt, this.camera);
    this.vfx.trails.update(dt);
    this.vfx.shockwaves.update(dt);
    this.vfx.floatingText.update(dt);
    this.background.update(dt);

    // Screen flash decay
    if (this.flashAlpha > 0) {
      this.flashAlpha -= dt * 3;
      if (this.flashAlpha < 0) this.flashAlpha = 0;
      if (this.flashOverlay) {
        this.flashOverlay.style.opacity = this.flashAlpha;
      }
    }
  }

  updateOrbitLights(dt) {
    this.orbitAngle += dt * 0.3;
    const r = 10;
    this.orbitLight1.position.x = Math.cos(this.orbitAngle) * r;
    this.orbitLight1.position.y = Math.sin(this.orbitAngle * 0.7) * r * 0.5;
    this.orbitLight2.position.x = Math.cos(this.orbitAngle + Math.PI) * r;
    this.orbitLight2.position.y = Math.sin(this.orbitAngle * 0.7 + Math.PI) * r * 0.5;
  }

  resolveCollisions() {
    const playerProjPos = this.projectiles.getPlayerProjPos();
    const invaderProjPositions = this.projectiles.getInvaderProjPositions();
    const aliveInvaders = this.invaderGrid.getAlive();
    const invaderBounds = aliveInvaders.map(inv => inv.getBounds());

    // Shield erosion callback
    const shieldErode = (pos, radius) => {
      this.shields.erode(pos, radius);
    };

    // Player projectile vs invaders
    if (playerProjPos) {
      const hit = this.collisions.checkPlayerProjectile(
        playerProjPos,
        invaderBounds,
        aliveInvaders,
        shieldErode
      );
      if (hit) {
        this.onInvaderKilled(hit.invader, hit.index);
        this.projectiles.removePlayerProjectile();
      } else {
        // Check vs mystery ship
        if (this.mysteryShip.isAlive) {
          const msHit = this.collisions.checkMysteryShip(playerProjPos, this.mysteryShip.getBounds());
          if (msHit) {
            this.onMysteryShipKilled();
            this.projectiles.removePlayerProjectile();
          }
        }
      }

      // Player projectile vs shields
      this.collisions.checkProjectileVsShields(playerProjPos, shieldErode);
      if (this.collisions.shieldHit) {
        this.projectiles.removePlayerProjectile();
        this.collisions.shieldHit = false;
      }
    }

    // Invader projectiles vs player
    for (let i = invaderProjPositions.length - 1; i >= 0; i--) {
      const projPos = invaderProjPositions[i];
      // vs shields first
      this.collisions.checkProjectileVsShields(projPos, shieldErode);
      if (this.collisions.shieldHit) {
        this.projectiles.removeInvaderProjectile(i);
        this.collisions.shieldHit = false;
        continue;
      }
      // vs player
      if (this.collisions.checkInvaderProjectile(projPos, this.player.getBounds())) {
        this.onPlayerHit();
        this.projectiles.removeInvaderProjectile(i);
      }
    }

    // Player vs invaders (body collision)
    if (this.collisions.checkInvaderDescent(invaderBounds, this.player.getBounds())) {
      this.onPlayerHit();
    }
  }

  onInvaderKilled(invader, index) {
    const basePoints = invader.points;
    const waveMult = this.waveManager.getMultiplier();
    const comboMult = this.scoreSystem.onKill(performance.now());
    const totalPoints = basePoints * waveMult * comboMult;

    this.scoreSystem.add(totalPoints, comboMult);

    // VFX
    const pos = invader.mesh.position.clone();
    const color = invader.emissiveColor;

    // Hit-stop (light)
    this.vfx.hitStop.trigger(60);

    // Camera shake
    this.vfx.shake.addTrauma(0.3);

    // Flash light
    this.flashLight.position.copy(pos);
    this.flashLight.intensity = 5;
    setTimeout(() => { this.flashLight.intensity = 0; }, 100);

    // Particle burst
    this.vfx.particles.burst(pos, 30, color, 1.5, 4);

    // Shockwave ring
    this.vfx.shockwaves.emit(pos, 2.0, color, 0.6);

    // Floating score text
    this.vfx.floatingText.show(pos, `+${totalPoints}`, color, 24, 1.2);

    // Audio
    this.audio.playSFX('invaderKill', 1.0 + (5 - invader.row) * 0.15);

    // Remove invader
    invader.die();
  }

  onPlayerHit() {
    this.player.takeDamage();

    // VFX
    const pos = this.player.mesh.position.clone();

    // Hit-stop (heavy)
    this.vfx.hitStop.trigger(120);

    // Camera shake
    this.vfx.shake.addTrauma(0.8);

    // Particles
    this.vfx.particles.burst(pos, 20, 0xffffff, 0.8, 3);

    // Audio
    this.audio.playSFX('playerHit');

    // Flash player ship
    this.player.flashHit();

    // Check death
    if (this.player.hp <= 0) {
      this.onGameOver();
    }
  }

  onMysteryShipKilled() {
    const points = this.mysteryShip.points;
    const waveMult = this.waveManager.getMultiplier();
    const totalPoints = points * waveMult;

    this.scoreSystem.add(totalPoints, 1);

    const pos = this.mysteryShip.mesh.position.clone();

    // Hit-stop (dramatic)
    this.vfx.hitStop.trigger(200);

    // Camera shake (heavy)
    this.vfx.shake.addTrauma(1.5);

    // Screen flash
    this.flashAlpha = 0.6;

    // Particles
    this.vfx.particles.burst(pos, 80, 0xff00ff, 3, 6);

    // Shockwave rings (2 staggered)
    this.vfx.shockwaves.emit(pos, 4.0, 0xff00ff, 0.8);
    setTimeout(() => {
      this.vfx.shockwaves.emit(pos, 3.0, 0xffffff, 0.6);
    }, 100);

    // Floating text
    this.vfx.floatingText.show(pos, `+${totalPoints}`, 0xffd700, 36, 2);

    // Audio
    this.audio.playSFX('mysteryKill');

    // Despawn
    this.mysteryShip.despawn();
  }

  onWaveClear() {
    this.state = 'waveClear';
    this.waveClearTimer = 0;

    // VFX
    this.vfx.hitStop.trigger(300);
    this.vfx.shake.addTrauma(0.5);

    // Celebration particles
    for (let i = 0; i < 5; i++) {
      const x = (Math.random() - 0.5) * 10;
      const y = (Math.random() - 0.5) * 6;
      const z = 0;
      const color = [0xff0000, 0x00ff00, 0x0000ff, 0xffff00, 0xff00ff][i];
      this.vfx.particles.burst(new THREE.Vector3(x, y, z), 20, color, 2, 5);
    }

    // Floating text
    this.vfx.floatingText.show(
      new THREE.Vector3(0, 2, 0),
      `WAVE ${this.waveManager.getWave()} COMPLETE`,
      0xffd700,
      32,
      2.5
    );

    // HUD
    this.hud.showWaveComplete(this.waveManager.getWave());

    // Audio
    this.audio.playSFX('waveClear');
  }

  onGameOver() {
    this.state = 'gameOver';
    this.gameOverTimer = 0;

    // Audio
    this.audio.playSFX('gameOver');
    this.audio.stopMusic();

    // VFX
    this.vfx.hitStop.trigger(400);
    this.vfx.shake.addTrauma(1.2);

    // Big explosion at player position
    this.vfx.particles.burst(
      this.player.mesh.position.clone(),
      60,
      0xff4444,
      2,
      5
    );

    // HUD
    const stats = {
      score: this.scoreSystem.getScore(),
      wave: this.waveManager.getWave(),
      invadersKilled: this.waveManager.getTotalKilled(),
      accuracy: 0 // simplified
    };
    this.hud.showGameOver(stats);
  }

  dispose() {
    this.tracker.disposeAll();
    if (this.hud) this.hud.dispose();
    this.audio.stopMusic();
  }
}

import { clamp } from 'shared/math/MathUtils.js';

export class CollisionSystem {
  constructor() {
    this.shieldHit = false;
  }

  /**
   * Check player projectile against all invader bounds.
   * Returns { hit: true, invader, index } or { hit: false }.
   */
  checkPlayerProjectile(projPos, invaderBounds, aliveInvaders, shieldErodeFn) {
    // Check against each invader
    for (let i = 0; i < invaderBounds.length; i++) {
      const b = invaderBounds[i];
      if (!b) continue;
      if (this._pointInAABB(projPos.x, projPos.y, b)) {
        return { hit: true, invader: aliveInvaders[i], index: i };
      }
    }
    return { hit: false };
  }

  /**
   * Check invader projectile against player bounds.
   */
  checkInvaderProjectile(projPos, playerBounds) {
    return this._pointInAABB(projPos.x, projPos.y, playerBounds);
  }

  /**
   * Check player projectile against mystery ship bounds.
   */
  checkMysteryShip(projPos, shipBounds) {
    if (!shipBounds) return false;
    return this._pointInAABB(projPos.x, projPos.y, shipBounds);
  }

  /**
   * Check if projectile hit any shield.
   */
  checkProjectileVsShields(projPos, shieldErodeFn) {
    this.shieldHit = false;
    shieldErodeFn(projPos, 0.4);
    // We always erode; the shield itself tracks if cells were destroyed
    // Game layer checks via shieldHit flag set by erode returning true
  }

  /**
   * Check if any invader has descended below threshold (body collision with player).
   */
  checkInvaderDescent(invaderBounds, playerBounds) {
    for (const b of invaderBounds) {
      if (!b) continue;
      if (b.minY <= playerBounds.maxY && b.maxY >= playerBounds.minY) {
        if (b.maxX >= playerBounds.minX && b.minX <= playerBounds.maxX) {
          return true;
        }
      }
    }
    return false;
  }

  _pointInAABB(px, py, b) {
    return px >= b.minX && px <= b.maxX && py >= b.minY && py <= b.maxY;
  }
}

