    this.scene.add(this.orbitLight2);

    // Player attached light
    this.playerLight = new THREE.PointLight(0x0088ff, 1.5, 8);
    this.scene.add(this.playerLight);

    // Flash light for explosions
    this.flashLight = new THREE.PointLight(0xffffff, 0, 20);
    this.scene.add(this.flashLight);

    // Screen flash overlay
    this.flashOverlay = document.getElementById('screen-flash');
    this.flashAlpha = 0;

    // Background
    this.background = new Background(this.scene, this.tracker);
    this.background.init();

    // Player
    this.player = new Player(this.scene, this.tracker);
    this.player.init();

    // Invader grid
    this.invaderGrid = new InvaderGrid(this.scene, this.tracker);
    this.invaderGrid.init(1);

    // Shields
    this.shields = new Shields(this.scene, this.tracker);
    this.shields.init();

    // Projectiles
    this.projectiles = new ProjectileSystem(this.scene, this.tracker);
    this.projectiles.init();

    // Mystery ship
    this.mysteryShip = new MysteryShip(this.scene, this.tracker);
    this.mysteryShip.init();

    // Wave manager
    this.waveManager = new WaveManager();

    // Score system
    this.scoreSystem = new ScoreSystem();

    // Collision system
    this.collisions = new CollisionSystem();

    // HUD
    this.hud = new HUD();
    this.hud.init();

    // Start music
    this.audio.startMusic();

    this.state = 'playing';
  }

  startWave(waveNum) {
    this.invaderGrid.reset(waveNum);
    this.shields.reset();
    this.projectiles.clear();
    this.mysteryShip.despawn();
    this.waveManager.advanceWave();
    this.scoreSystem.onWaveClear();
    this.audio.setWave(waveNum);
  }

  update(dt) {
    if (this.state === 'menu') {
      if (this.input.wasJustPressed('fire')) {
        this.init();
      }
      return;
    }

    if (this.state === 'gameOver') {
      this.gameOverTimer += dt;
      this.vfx.particles.update(dt);
      this.vfx.shockwaves.update(dt);
      this.vfx.floatingText.update(dt);
      this.background.update(dt);
      this.updateOrbitLights(dt);
      if (this.input.wasJustPressed('fire') && this.gameOverTimer > 2) {
        this.gameOverTimer = 0;
        this.init();
      }
      return;
    }

    if (this.state === 'waveClear') {
      this.waveClearTimer += dt;
      this.vfx.particles.update(dt);
      this.vfx.shockwaves.update(dt);
      this.vfx.floatingText.update(dt);
      this.background.update(dt);
      this.updateOrbitLights(dt);
      if (this.waveClearTimer > 3) {
        this.state = 'playing';
        this.startWave(this.waveManager.getWave() + 1);
      }
      return;
    }

    // Hit-stop check
    const timescale = this.vfx.hitStop.getTimescale();
    const gameDt = dt * timescale;

    // Update orbiting lights
    this.updateOrbitLights(dt);

    // Player light follows ship
    this.playerLight.position.copy(this.player.group.position);
    this.playerLight.position.z += 2;

    // Player update
    this.player.update(gameDt, this.input);

    // Player firing
    const firePos = this.player.fire();
    if (firePos) {
      this.projectiles.firePlayer(firePos);
      this.audio.playSFX('playerShoot');
    }

    // Thruster particles
    this.thrusterTimer += dt;
    if (this.thrusterTimer > 0.05) {
      this.thrusterTimer = 0;
      const count = Math.abs(this.input.getAxis('horizontal')) > 0.1 ? 3 : 1;
      this.vfx.particles.burst(
        this.player.group.position.clone(),
        count,
        0x0088ff,
        0.3,
        1.5
      );
    }

    // Invader grid update
    this.invaderGrid.update(gameDt);

    // Invader firing
    const invaderFirePos = this.invaderGrid.fire(gameDt);
    if (invaderFirePos) {
      this.projectiles.fireInvader(invaderFirePos);
      this.audio.playSFX('invaderShoot');
    }

    // Projectile update
    this.projectiles.update(gameDt);

    // Mystery ship update
    this.mysteryShip.update(gameDt);

    // Collision detection
    this.resolveCollisions();

    // Check wave clear
    if (this.invaderGrid.getAlive().length === 0 && this.state === 'playing') {
      this.onWaveClear();
    }

    // Check invader descent
    if (this.invaderGrid.checkDescent() && this.state === 'playing') {
      this.onGameOver();
    }

    // Update HUD
    this.hud.update(
      this.scoreSystem.getScore(),
      this.waveManager.getWave(),
      this.player.hp,
      CONFIG.PLAYER_MAX_HP,
      this.scoreSystem.getCombo(),
      this.scoreSystem.getMultiplier()
    );

    // Update VFX
    this.vfx.particles.update(dt);
    this.vfx.shake.update(dt, this.camera);
    this.vfx.trails.update(dt);
    this.vfx.shockwaves.update(dt);
    this.vfx.floatingText.update(dt);
    this.background.update(dt);

    // Screen flash decay
    if (this.flashAlpha > 0) {
      this.flashAlpha -= dt * 3;
      if (this.flashAlpha < 0) this.flashAlpha = 0;
      if (this.flashOverlay) {
        this.flashOverlay.style.opacity = this.flashAlpha;
      }
    }
  }

  updateOrbitLights(dt) {
    this.orbitAngle += dt * 0.3;
    const r = 10;
    this.orbitLight1.position.x = Math.cos(this.orbitAngle) * r;
    this.orbitLight1.position.y = Math.sin(this.orbitAngle * 0.7) * r * 0.5;
    this.orbitLight2.position.x = Math.cos(this.orbitAngle + Math.PI) * r;
    this.orbitLight2.position.y = Math.sin(this.orbitAngle * 0.7 + Math.PI) * r * 0.5;
  }

  resolveCollisions() {
    const playerProjPos = this.projectiles.getPlayerProjPos();
    const invaderProjPositions = this.projectiles.getInvaderProjPositions();
    const aliveInvaders = this.invaderGrid.getAlive();
    const invaderBounds = aliveInvaders.map(inv => inv.getBounds());

    // Shield erosion callback
    const shieldErode = (pos, radius) => {
      this.shields.erode(pos, radius);
    };

    // Player projectile vs invaders
    if (playerProjPos) {
      const hit = this.collisions.checkPlayerProjectile(
        playerProjPos,
        invaderBounds,
        aliveInvaders,
        shieldErode
      );
      if (hit) {
        this.onInvaderKilled(hit.invader, hit.index);
        this.projectiles.removePlayerProjectile();
      } else {
        // Check vs mystery ship
        if (this.mysteryShip.isAlive) {
          const msHit = this.collisions.checkMysteryShip(playerProjPos, this.mysteryShip.getBounds());
          if (msHit) {
            this.onMysteryShipKilled();
            this.projectiles.removePlayerProjectile();
          }
        }
      }

      // Player projectile vs shields
      this.collisions.checkProjectileVsShields(playerProjPos, shieldErode);
      if (this.collisions.shieldHit) {
        this.projectiles.removePlayerProjectile();
        this.collisions.shieldHit = false;
      }
    }

    // Invader projectiles vs player
    for (let i = invaderProjPositions.length - 1; i >= 0; i--) {
      const projPos = invaderProjPositions[i];
      // vs shields first
      this.collisions.checkProjectileVsShields(projPos, shieldErode);
      if (this.collisions.shieldHit) {
        this.projectiles.removeInvaderProjectile(i);
        this.collisions.shieldHit = false;
        continue;
      }
      // vs player
      if (this.collisions.checkInvaderProjectile(projPos, this.player.getBounds())) {
        this.onPlayerHit();
        this.projectiles.removeInvaderProjectile(i);
      }
    }

    // Player vs invaders (body collision)
    if (this.collisions.checkInvaderDescent(invaderBounds, this.player.getBounds())) {
      this.onPlayerHit();
    }
  }

  onInvaderKilled(invader, index) {
    const basePoints = invader.points;
    const waveMult = this.waveManager.getMultiplier();
    const comboMult = this.scoreSystem.onKill(performance.now());
    const totalPoints = basePoints * waveMult * comboMult;

    this.scoreSystem.add(totalPoints, comboMult);

    // VFX
    const pos = invader.mesh.position.clone();
    const color = invader.emissiveColor;

    // Hit-stop (light)
    this.vfx.hitStop.trigger(60);

    // Camera shake
    this.vfx.shake.addTrauma(0.3);

    // Flash light
    this.flashLight.position.copy(pos);
    this.flashLight.intensity = 5;
    setTimeout(() => { this.flashLight.intensity = 0; }, 100);

    // Particle burst
    this.vfx.particles.burst(pos, 30, color, 1.5, 4);

    // Shockwave ring
    this.vfx.shockwaves.emit(pos, 2.0, color, 0.6);

    // Floating score text
    this.vfx.floatingText.show(pos, `+${totalPoints}`, color, 24, 1.2);

    // Audio
    this.audio.playSFX('invaderKill', 1.0 + (5 - invader.row) * 0.15);

    // Remove invader
    invader.die();
  }

  onPlayerHit() {
    this.player.takeDamage();

    // VFX
    const pos = this.player.group.position.clone();

    // Hit-stop (heavy)
    this.vfx.hitStop.trigger(120);

    // Camera shake
    this.vfx.shake.addTrauma(0.8);

    // Particles
    this.vfx.particles.burst(pos, 20, 0xffffff, 0.8, 3);

    // Audio
    this.audio.playSFX('playerHit');

    // Flash player ship
    this.player.flashHit();

    // Check death
    if (this.player.hp <= 0) {
      this.onGameOver();
    }
  }

  onMysteryShipKilled() {
    const points = this.mysteryShip.points;
    const waveMult = this.waveManager.getMultiplier();
    const totalPoints = points * waveMult;

    this.scoreSystem.add(totalPoints, 1);

    const pos = this.mysteryShip.mesh.position.clone();

    // Hit-stop (dramatic)
    this.vfx.hitStop.trigger(200);

    // Camera shake (heavy)
    this.vfx.shake.addTrauma(1.5);

    // Screen flash
    this.flashAlpha = 0.6;

    // Particles
    this.vfx.particles.burst(pos, 80, 0xff00ff, 3, 6);

    // Shockwave rings (2 staggered)
    this.vfx.shockwaves.emit(pos, 4.0, 0xff00ff, 0.8);
    setTimeout(() => {
      this.vfx.shockwaves.emit(pos, 3.0, 0xffffff, 0.6);
    }, 100);

    // Floating text
    this.vfx.floatingText.show(pos, `+${totalPoints}`, 0xffd700, 36, 2);

    // Audio
    this.audio.playSFX('mysteryKill');

    // Despawn
    this.mysteryShip.despawn();
  }

  onWaveClear() {
    this.state = 'waveClear';
    this.waveClearTimer = 0;

    // VFX
    this.vfx.hitStop.trigger(300);
    this.vfx.shake.addTrauma(0.5);

    // Celebration particles
    for (let i = 0; i < 5; i++) {
      const x = (Math.random() - 0.5) * 10;
      const y = (Math.random() - 0.5) * 6;
      const z = 0;
      const color = [0xff0000, 0x00ff00, 0x0000ff, 0xffff00, 0xff00ff][i];
      this.vfx.particles.burst(new THREE.Vector3(x, y, z), 20, color, 2, 5);
    }

    // Floating text
    this.vfx.floatingText.show(
      new THREE.Vector3(0, 2, 0),
      `WAVE ${this.waveManager.getWave()} COMPLETE`,
      0xffd700,
      32,
      2.5
    );

    // HUD
    this.hud.showWaveComplete(this.waveManager.getWave());

    // Audio
    this.audio.playSFX('waveClear');
  }

  onGameOver() {
    this.state = 'gameOver';
    this.gameOverTimer = 0;

    // Audio
    this.audio.playSFX('gameOver');
    this.audio.stopMusic();

    // VFX
    this.vfx.hitStop.trigger(400);
    this.vfx.shake.addTrauma(1.2);

    // Big explosion at player position
    this.vfx.particles.burst(
      this.player.mesh.position.clone(),
      60,
      0xff4444,
      2,
      5
    );

    // HUD
    const stats = {
      score: this.scoreSystem.getScore(),
      wave: this.waveManager.getWave(),
      invadersKilled: this.waveManager.getTotalKilled(),
      accuracy: 0 // simplified
    };
    this.hud.showGameOver(stats);
  }

  dispose() {
    this.tracker.disposeAll();
    if (this.hud) this.hud.dispose();
    this.audio.stopMusic();
  }
}

import * as THREE from 'three';
import { Game } from './Space_Invaders/Game.js';

let gameInstance = null;

async function boot() {
  await waitForAudio();

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.0;
  document.getElementById('canvas-container').appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050510);
  scene.fog = new THREE.FogExp2(0x050510, 0.015);

  const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 100);
  camera.position.set(0, 0, 14);
  camera.lookAt(0, 0, 0);

  const { createComposer } = await import('shared/rendering/EffectComposerSetup.js');
  const { composer } = createComposer(renderer, window.innerWidth, window.innerHeight, {
    strength: 0.6, radius: 0.4, threshold: 0.85,
  });

  const { InputManager } = await import('shared/input/InputManager.js');
  const { ParticleManager } = await import('shared/vfx/ParticleManager.js');
  const { CameraShake } = await import('shared/vfx/CameraShake.js');
  const { HitStop } = await import('shared/vfx/HitStop.js');
  const { MotionTrails } = await import('shared/vfx/MotionTrails.js');
  const { ShockwaveRings } = await import('shared/vfx/ShockwaveRings.js');
  const { FloatingText } = await import('shared/vfx/FloatingText.js');
  const { AudioManager } = await import('shared/audio/AudioManager.js');

  const input = new InputManager();
  const particles = new ParticleManager(scene, 500);
  const cameraShake = new CameraShake();
  const hitStop = new HitStop();
  const motionTrails = new MotionTrails(scene);
  const shockwaves = new ShockwaveRings(scene);
  const floatingText = new FloatingText(scene);
  const audio = new AudioManager();

  audio.init();
  audio.setVolume(0.3);

  gameInstance = new Game(scene, camera, composer, input, {
    particles,
    shake: cameraShake,
    hitStop,
    trails: motionTrails,
    shockwaves,
    floatingText,
  }, audio);

  gameInstance.init();

  window.addEventListener('resize', () => {
    const w = window.innerWidth, h = window.innerHeight;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
    composer.setSize(w, h);
  });

  const clock = new THREE.Clock();
  function loop() {
    requestAnimationFrame(loop);
    const rawDt = Math.min(clock.getDelta(), 0.05);
    input.update();
    hitStop.update();
    const timescale = hitStop.getTimescale();
    const dt = timescale > 0 ? rawDt : 0;
    gameInstance.update(dt, rawDt);
    cameraShake.update(rawDt, camera);
    particles.update(dt);
    motionTrails.update(dt);
    shockwaves.update(dt);
    floatingText.update(dt);
    composer.render();
  }
  loop();
}

function waitForAudio() {
  return new Promise((resolve) => {
    const el = document.getElementById('start-overlay');
    const btn = document.getElementById('btn-start');
    const handler = () => {
      el.removeEventListener('click', handler);
      el.removeEventListener('touchstart', handler);
      btn.removeEventListener('click', handler);
      el.style.opacity = '0';
      setTimeout(() => el.style.display = 'none', 500);
      resolve();
    };
    el.addEventListener('click', handler);
    el.addEventListener('touchstart', handler);
    btn.addEventListener('click', handler);
  });
}

boot();

import { clamp } from 'shared/math/MathUtils.js';

export class CollisionSystem {
  constructor() {
    this.shieldHit = false;
  }

  /**
   * Check player projectile against all invader bounds.
   * Returns { hit: true, invader, index } or { hit: false }.
   */
  checkPlayerProjectile(projPos, invaderBounds, aliveInvaders, shieldErodeFn) {
    // Check against each invader
    for (let i = 0; i < invaderBounds.length; i++) {
      const b = invaderBounds[i];
      if (!b) continue;
      if (this._pointInAABB(projPos.x, projPos.y, b)) {
        return { hit: true, invader: aliveInvaders[i], index: i };
      }
    }
    return { hit: false };
  }

  /**
   * Check invader projectile against player bounds.
   */
  checkInvaderProjectile(projPos, playerBounds) {
    return this._pointInAABB(projPos.x, projPos.y, playerBounds);
  }

  /**
   * Check player projectile against mystery ship bounds.
   */
  checkMysteryShip(projPos, shipBounds) {
    if (!shipBounds) return false;
    return this._pointInAABB(projPos.x, projPos.y, shipBounds);
  }

  /**
   * Check if projectile hit any shield.
   */
  checkProjectileVsShields(projPos, shieldErodeFn) {
    this.shieldHit = false;
    shieldErodeFn(projPos, 0.4);
    // We always erode; the shield itself tracks if cells were destroyed
    // Game layer checks via shieldHit flag set by erode returning true
  }

  /**
   * Check if any invader has descended below threshold (body collision with player).
   */
  checkInvaderDescent(invaderBounds, playerBounds) {
    for (const b of invaderBounds) {
      if (!b) continue;
      if (b.minY <= playerBounds.maxY && b.maxY >= playerBounds.minY) {
        if (b.maxX >= playerBounds.minX && b.minX <= playerBounds.maxX) {
          return true;
        }
      }
    }
    return false;
  }

  _pointInAABB(px, py, b) {
    return px >= b.minX && px <= b.maxX && py >= b.minY && py <= b.maxY;
  }
}

export class WaveManager {
  constructor() {
    this._wave = 1;
    this._totalKilled = 0;
  }

  getWave() {
    return this._wave;
  }

  getMultiplier() {
    return this._wave;
  }

  getTotalKilled() {
    return this._totalKilled;
  }

  advanceWave() {
    this._wave++;
  }

  onInvaderKilled() {
    this._totalKilled++;
  }

  reset() {
    this._wave = 1;
    this._totalKilled = 0;
  }
}

export class ScoreSystem {
  constructor() {
    this._score = 0;
    this._combo = 0;
    this._multiplier = 1;
    this._lastKillTime = 0;
    this._totalKills = 0;
    this._totalShots = 0;
  }

  onShoot() {
    this._totalShots++;
  }

  onKill(currentTime) {
    this._totalKills++;
    const elapsed = (currentTime - this._lastKillTime) / 1000;
    if (elapsed < 1.5 && this._combo < 5) {
      this._combo++;
      this._multiplier = this._combo;
    } else if (elapsed >= 1.5) {
      this._combo = 0;
      this._multiplier = 1;
    }
    this._lastKillTime = currentTime;
    return this._multiplier;
  }

  add(points, _multiplier) {
    this._score += points;
  }

  getScore() { return this._score; }
  getCombo() { return this._combo; }
  getMultiplier() { return this._multiplier; }
  getTotalKills() { return this._totalKills; }
  getTotalShots() { return this._totalShots; }
  getAccuracy() {
    if (this._totalShots === 0) return 100;
    return Math.round((this._totalKills / this._totalShots) * 100);
  }

  onWaveClear() {
    // Reset combo between waves
    this._combo = 0;
    this._multiplier = 1;
  }

  reset() {
    this._score = 0;
    this._combo = 0;
    this._multiplier = 1;
    this._lastKillTime = 0;
    this._totalKills = 0;
    this._totalShots = 0;
  }
}

import * as THREE from 'three';
import { Player } from './Player.js';
import { InvaderGrid } from './InvaderGrid.js';
import { Shields } from './Shields.js';
import { ProjectileSystem } from './ProjectileSystem.js';
import { MysteryShip } from './MysteryShip.js';
import { WaveManager } from './WaveManager.js';
import { ScoreSystem } from './ScoreSystem.js';
import { CollisionSystem } from './CollisionSystem.js';
import { Background } from './Background.js';
import { HUD } from './HUD.js';
import { MemoryTracker } from 'shared/memory/MemoryTracker.js';
import { CONFIG } from './config.js';

export class Game {
  constructor(scene, camera, composer, input, vfx, audio) {
    this.scene = scene;
    this.camera = camera;
    this.composer = composer;
    this.input = input;
    this.vfx = vfx;
    this.audio = audio;

    this.tracker = new MemoryTracker();
    this.state = 'menu';
    this.waveClearTimer = 0;
    this.gameOverTimer = 0;

    // Subsystems
    this.player = null;
    this.invaderGrid = null;
    this.shields = null;
    this.projectiles = null;
    this.mysteryShip = null;
    this.waveManager = null;
    this.scoreSystem = null;
    this.collisions = null;
    this.background = null;
    this.hud = null;

    // Lighting
    this.orbitLight1 = null;
    this.orbitLight2 = null;
    this.playerLight = null;
    this.flashLight = null;
    this.orbitAngle = 0;

    // Screen flash
    this.flashOverlay = null;
    this.flashAlpha = 0;

    // Thruster timer
    this.thrusterTimer = 0;
  }

  init() {
    // Clear scene
    while (this.scene.children.length > 0) {
      this.scene.remove(this.scene.children[0]);
    }
    this.tracker.disposeAll();

    // Ambient light
    const ambient = new THREE.AmbientLight(0x334455, 0.4);
    this.scene.add(ambient);

    // Orbiting lights
    this.orbitLight1 = new THREE.PointLight(0x00ffff, 2, 30);
    this.orbitLight1.position.set(5, 5, 5);
    this.scene.add(this.orbitLight1);

    this.orbitLight2 = new THREE.PointLight(0xff00ff, 2, 30);
    this.orbitLight2.position.set(-5, -5, 5);
    this.scene.add(this.orbitLight2);

    // Player attached light
    this.playerLight = new THREE.PointLight(0x0088ff, 1.5, 8);
    this.scene.add(this.playerLight);

    // Flash light for explosions
    this.flashLight = new THREE.PointLight(0xffffff, 0, 20);
    this.scene.add(this.flashLight);

    // Screen flash overlay
    this.flashOverlay = document.getElementById('screen-flash');
    this.flashAlpha = 0;

    // Background
    this.background = new Background(this.scene, this.tracker);
    this.background.init();

    // Player
    this.player = new Player(this.scene, this.tracker);
    this.player.init();

    // Invader grid
    this.invaderGrid = new InvaderGrid(this.scene, this.tracker);
    this.invaderGrid.init(1);

    // Shields
    this.shields = new Shields(this.scene, this.tracker);
    this.shields.init();

    // Projectiles
    this.projectiles = new ProjectileSystem(this.scene, this.tracker);
    this.projectiles.init();

    // Mystery ship
    this.mysteryShip = new MysteryShip(this.scene, this.tracker);
    this.mysteryShip.init();

    // Wave manager
    this.waveManager = new WaveManager();

    // Score system
    this.scoreSystem = new ScoreSystem();

    // Collision system
    this.collisions = new CollisionSystem();

    // HUD
    this.hud = new HUD();
    this.hud.init();

    // Start music
    this.audio.startMusic();

    this.state = 'playing';
  }

  startWave(waveNum) {
    this.invaderGrid.reset(waveNum);
    this.shields.reset();
    this.projectiles.clear();
    this.mysteryShip.despawn();
    this.waveManager.advanceWave();
    this.scoreSystem.onWaveClear();
    this.audio.setWave(waveNum);
  }

  update(dt) {
    if (this.state === 'menu') {
      if (this.input.wasJustPressed('fire')) {
        this.init();
      }
      return;
    }

    if (this.state === 'gameOver') {
      this.gameOverTimer += dt;
      this.vfx.particles.update(dt);
      this.vfx.shockwaves.update(dt);
      this.vfx.floatingText.update(dt);
      this.background.update(dt);
      this.updateOrbitLights(dt);
      if (this.input.wasJustPressed('fire') && this.gameOverTimer > 2) {
        this.gameOverTimer = 0;
        this.init();
      }
      return;
    }

    if (this.state === 'waveClear') {
      this.waveClearTimer += dt;
      this.vfx.particles.update(dt);
      this.vfx.shockwaves.update(dt);
      this.vfx.floatingText.update(dt);
      this.background.update(dt);
      this.updateOrbitLights(dt);
      if (this.waveClearTimer > 3) {
        this.state = 'playing';
        this.startWave(this.waveManager.getWave() + 1);
      }
      return;
    }

    // Hit-stop check
    const timescale = this.vfx.hitStop.getTimescale();
    const gameDt = dt * timescale;

    // Update orbiting lights
    this.updateOrbitLights(dt);

    // Player light follows ship
    this.playerLight.position.copy(this.player.group.position);
    this.playerLight.position.z += 2;

    // Player update
    this.player.update(gameDt, this.input);

    // Player firing
    const firePos = this.player.fire();
    if (firePos) {
      this.projectiles.firePlayer(firePos);
      this.audio.playSFX('playerShoot');
    }

    // Thruster particles
    this.thrusterTimer += dt;
    if (this.thrusterTimer > 0.05) {
      this.thrusterTimer = 0;
      const count = Math.abs(this.input.getAxis('horizontal')) > 0.1 ? 3 : 1;
      this.vfx.particles.burst(
        this.player.group.position.clone(),
        count,
        0x0088ff,
        0.3,
        1.5
      );
    }

    // Invader grid update
    this.invaderGrid.update(gameDt);

    // Invader firing
    const invaderFirePos = this.invaderGrid.fire(gameDt);
    if (invaderFirePos) {
      this.projectiles.fireInvader(invaderFirePos);
      this.audio.playSFX('invaderShoot');
    }

    // Projectile update
    this.projectiles.update(gameDt);

    // Mystery ship update
    this.mysteryShip.update(gameDt);

    // Collision detection
    this.resolveCollisions();

    // Check wave clear
    if (this.invaderGrid.getAlive().length === 0 && this.state === 'playing') {
      this.onWaveClear();
    }

    // Check invader descent
    if (this.invaderGrid.checkDescent() && this.state === 'playing') {
      this.onGameOver();
    }

    // Update HUD
    this.hud.update(
      this.scoreSystem.getScore(),
      this.waveManager.getWave(),
      this.player.hp,
      CONFIG.PLAYER_MAX_HP,
      this.scoreSystem.getCombo(),
      this.scoreSystem.getMultiplier()
    );

    // Update VFX
    this.vfx.particles.update(dt);
    this.vfx.shake.update(dt, this.camera);
    this.vfx.trails.update(dt);
    this.vfx.shockwaves.update(dt);
    this.vfx.floatingText.update(dt);
    this.background.update(dt);

    // Screen flash decay
    if (this.flashAlpha > 0) {
      this.flashAlpha -= dt * 3;
      if (this.flashAlpha < 0) this.flashAlpha = 0;
      if (this.flashOverlay) {
        this.flashOverlay.style.opacity = this.flashAlpha;
      }
    }
  }

  updateOrbitLights(dt) {
    this.orbitAngle += dt * 0.3;
    const r = 10;
    this.orbitLight1.position.x = Math.cos(this.orbitAngle) * r;
    this.orbitLight1.position.y = Math.sin(this.orbitAngle * 0.7) * r * 0.5;
    this.orbitLight2.position.x = Math.cos(this.orbitAngle + Math.PI) * r;
    this.orbitLight2.position.y = Math.sin(this.orbitAngle * 0.7 + Math.PI) * r * 0.5;
  }

  resolveCollisions() {
    const playerProjPos = this.projectiles.getPlayerProjPos();
    const invaderProjPositions = this.projectiles.getInvaderProjPositions();
    const aliveInvaders = this.invaderGrid.getAlive();
    const invaderBounds = aliveInvaders.map(inv => inv.getBounds());

    // Shield erosion callback
    const shieldErode = (pos, radius) => {
      this.shields.erode(pos, radius);
    };

    // Player projectile vs invaders
    if (playerProjPos) {
      const hit = this.collisions.checkPlayerProjectile(
        playerProjPos,
        invaderBounds,
        aliveInvaders,
        shieldErode
      );
      if (hit) {
        this.onInvaderKilled(hit.invader, hit.index);
        this.projectiles.removePlayerProjectile();
      } else {
        // Check vs mystery ship
        if (this.mysteryShip.isAlive) {
          const msHit = this.collisions.checkMysteryShip(playerProjPos, this.mysteryShip.getBounds());
          if (msHit) {
            this.onMysteryShipKilled();
            this.projectiles.removePlayerProjectile();
          }
        }
      }

      // Player projectile vs shields
      this.collisions.checkProjectileVsShields(playerProjPos, shieldErode);
      if (this.collisions.shieldHit) {
        this.projectiles.removePlayerProjectile();
        this.collisions.shieldHit = false;
      }
    }

    // Invader projectiles vs player
    for (let i = invaderProjPositions.length - 1; i >= 0; i--) {
      const projPos = invaderProjPositions[i];
      // vs shields first
      this.collisions.checkProjectileVsShields(projPos, shieldErode);
      if (this.collisions.shieldHit) {
        this.projectiles.removeInvaderProjectile(i);
        this.collisions.shieldHit = false;
        continue;
      }
      // vs player
      if (this.collisions.checkInvaderProjectile(projPos, this.player.getBounds())) {
        this.onPlayerHit();
        this.projectiles.removeInvaderProjectile(i);
      }
    }

    // Player vs invaders (body collision)
    if (this.collisions.checkInvaderDescent(invaderBounds, this.player.getBounds())) {
      this.onPlayerHit();
    }
  }

  onInvaderKilled(invader, index) {
    const basePoints = invader.points;
    const waveMult = this.waveManager.getMultiplier();
    const comboMult = this.scoreSystem.onKill(performance.now());
    const totalPoints = basePoints * waveMult * comboMult;

    this.scoreSystem.add(totalPoints, comboMult);

    // VFX
    const pos = invader.mesh.position.clone();
    const color = invader.emissiveColor;

    // Hit-stop (light)
    this.vfx.hitStop.trigger(60);

    // Camera shake
    this.vfx.shake.addTrauma(0.3);

    // Flash light
    this.flashLight.position.copy(pos);
    this.flashLight.intensity = 5;
    setTimeout(() => { this.flashLight.intensity = 0; }, 100);

    // Particle burst
    this.vfx.particles.burst(pos, 30, color, 1.5, 4);

    // Shockwave ring
    this.vfx.shockwaves.emit(pos, 2.0, color, 0.6);

    // Floating score text
    this.vfx.floatingText.show(pos, `+${totalPoints}`, color, 24, 1.2);

    // Audio
    this.audio.playSFX('invaderKill', 1.0 + (5 - invader.row) * 0.15);

    // Remove invader
    invader.die();
  }

  onPlayerHit() {
    this.player.takeDamage();

    // VFX
    const pos = this.player.group.position.clone();

    // Hit-stop (heavy)
    this.vfx.hitStop.trigger(120);

    // Camera shake
    this.vfx.shake.addTrauma(0.8);

    // Particles
    this.vfx.particles.burst(pos, 20, 0xffffff, 0.8, 3);

    // Audio
    this.audio.playSFX('playerHit');

    // Flash player ship
    this.player.flashHit();

    // Check death
    if (this.player.hp <= 0) {
      this.onGameOver();
    }
  }

  onMysteryShipKilled() {
    const points = this.mysteryShip.points;
    const waveMult = this.waveManager.getMultiplier();
    const totalPoints = points * waveMult;

    this.scoreSystem.add(totalPoints, 1);

    const pos = this.mysteryShip.mesh.position.clone();

    // Hit-stop (dramatic)
    this.vfx.hitStop.trigger(200);

    // Camera shake (heavy)
    this.vfx.shake.addTrauma(1.5);

    // Screen flash
    this.flashAlpha = 0.6;

    // Particles
    this.vfx.particles.burst(pos, 80, 0xff00ff, 3, 6);

    // Shockwave rings (2 staggered)
    this.vfx.shockwaves.emit(pos, 4.0, 0xff00ff, 0.8);
    setTimeout(() => {
      this.vfx.shockwaves.emit(pos, 3.0, 0xffffff, 0.6);
    }, 100);

    // Floating text
    this.vfx.floatingText.show(pos, `+${totalPoints}`, 0xffd700, 36, 2);

    // Audio
    this.audio.playSFX('mysteryKill');

    // Despawn
    this.mysteryShip.despawn();
  }

  onWaveClear() {
    this.state = 'waveClear';
    this.waveClearTimer = 0;

    // VFX
    this.vfx.hitStop.trigger(300);
    this.vfx.shake.addTrauma(0.5);

    // Celebration particles
    for (let i = 0; i < 5; i++) {
      const x = (Math.random() - 0.5) * 10;
      const y = (Math.random() - 0.5) * 6;
      const z = 0;
      const color = [0xff0000, 0x00ff00, 0x0000ff, 0xffff00, 0xff00ff][i];
      this.vfx.particles.burst(new THREE.Vector3(x, y, z), 20, color, 2, 5);
    }

    // Floating text
    this.vfx.floatingText.show(
      new THREE.Vector3(0, 2, 0),
      `WAVE ${this.waveManager.getWave()} COMPLETE`,
      0xffd700,
      32,
      2.5
    );

    // HUD
    this.hud.showWaveComplete(this.waveManager.getWave());

    // Audio
    this.audio.playSFX('waveClear');
  }

  onGameOver() {
    this.state = 'gameOver';
    this.gameOverTimer = 0;

    // Audio
    this.audio.playSFX('gameOver');
    this.audio.stopMusic();

    // VFX
    this.vfx.hitStop.trigger(400);
    this.vfx.shake.addTrauma(1.2);

    // Big explosion at player position
    this.vfx.particles.burst(
      this.player.mesh.position.clone(),
      60,
      0xff4444,
      2,
      5
    );

    // HUD
    const stats = {
      score: this.scoreSystem.getScore(),
      wave: this.waveManager.getWave(),
      invadersKilled: this.waveManager.getTotalKilled(),
      accuracy: 0 // simplified
    };
    this.hud.showGameOver(stats);
  }

  dispose() {
    this.tracker.disposeAll();
    if (this.hud) this.hud.dispose();
    this.audio.stopMusic();
  }
}

import { clamp } from 'shared/math/MathUtils.js';

export class CollisionSystem {
  constructor() {
    this.shieldHit = false;
  }

  /**
   * Check player projectile against all invader bounds.
   * Returns { hit: true, invader, index } or { hit: false }.
   */
  checkPlayerProjectile(projPos, invaderBounds, aliveInvaders, shieldErodeFn) {
    // Check against each invader
    for (let i = 0; i < invaderBounds.length; i++) {
      const b = invaderBounds[i];
      if (!b) continue;
      if (this._pointInAABB(projPos.x, projPos.y, b)) {
        return { hit: true, invader: aliveInvaders[i], index: i };
      }
    }
    return { hit: false };
  }

  /**
   * Check invader projectile against player bounds.
   */
  checkInvaderProjectile(projPos, playerBounds) {
    return this._pointInAABB(projPos.x, projPos.y, playerBounds);
  }

  /**
   * Check player projectile against mystery ship bounds.
   */
  checkMysteryShip(projPos, shipBounds) {
    if (!shipBounds) return false;
    return this._pointInAABB(projPos.x, projPos.y, shipBounds);
  }

  /**
   * Check if projectile hit any shield.
   */
  checkProjectileVsShields(projPos, shieldErodeFn) {
    this.shieldHit = false;
    shieldErodeFn(projPos, 0.4);
    // We always erode; the shield itself tracks if cells were destroyed
    // Game layer checks via shieldHit flag set by erode returning true
  }

  /**
   * Check if any invader has descended below threshold (body collision with player).
   */
  checkInvaderDescent(invaderBounds, playerBounds) {
    for (const b of invaderBounds) {
      if (!b) continue;
      if (b.minY <= playerBounds.maxY && b.maxY >= playerBounds.minY) {
        if (b.maxX >= playerBounds.minX && b.minX <= playerBounds.maxX) {
          return true;
        }
      }
    }
    return false;
  }

  _pointInAABB(px, py, b) {
    return px >= b.minX && px <= b.maxX && py >= b.minY && py <= b.maxY;
  }
}

import * as THREE from 'three';
import { Game } from './Space_Invaders/Game.js';

let gameInstance = null;

async function boot() {
  await waitForAudio();

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.0;
  document.getElementById('canvas-container').appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050510);
  scene.fog = new THREE.FogExp2(0x050510, 0.015);

  const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 100);
  camera.position.set(0, 0, 14);
  camera.lookAt(0, 0, 0);

  const { createComposer } = await import('shared/rendering/EffectComposerSetup.js');
  const { composer } = createComposer(renderer, window.innerWidth, window.innerHeight, {
    strength: 0.6, radius: 0.4, threshold: 0.85,
  });

  const { InputManager } = await import('shared/input/InputManager.js');
  const { ParticleManager } = await import('shared/vfx/ParticleManager.js');
  const { CameraShake } = await import('shared/vfx/CameraShake.js');
  const { HitStop } = await import('shared/vfx/HitStop.js');
  const { MotionTrails } = await import('shared/vfx/MotionTrails.js');
  const { ShockwaveRings } = await import('shared/vfx/ShockwaveRings.js');
  const { FloatingText } = await import('shared/vfx/FloatingText.js');
  const { AudioManager } = await import('shared/audio/AudioManager.js');

  const input = new InputManager();
  const particles = new ParticleManager(scene, 500);
  const cameraShake = new CameraShake();
  const hitStop = new HitStop();
  const motionTrails = new MotionTrails(scene);
  const shockwaves = new ShockwaveRings(scene);
  const floatingText = new FloatingText(scene);
  const audio = new AudioManager();

  audio.init();
  audio.setVolume(0.3);

  gameInstance = new Game(scene, camera, composer, input, {
    particles,
    shake: cameraShake,
    hitStop,
    trails: motionTrails,
    shockwaves,
    floatingText,
  }, audio);

  gameInstance.init();

  window.addEventListener('resize', () => {
    const w = window.innerWidth, h = window.innerHeight;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
    composer.setSize(w, h);
  });

  const clock = new THREE.Clock();
  function loop() {
    requestAnimationFrame(loop);
    const rawDt = Math.min(clock.getDelta(), 0.05);
    input.update();
    hitStop.update();
    const timescale = hitStop.getTimescale();
    const dt = timescale > 0 ? rawDt : 0;
    gameInstance.update(dt, rawDt);
    cameraShake.update(rawDt, camera);
    particles.update(dt);
    motionTrails.update(dt);
    shockwaves.update(dt);
    floatingText.update(dt);
    composer.render();
  }
  loop();
}

function waitForAudio() {
  return new Promise((resolve) => {
    const el = document.getElementById('start-overlay');
    const btn = document.getElementById('btn-start');
    const handler = () => {
      el.removeEventListener('click', handler);
      el.removeEventListener('touchstart', handler);
      btn.removeEventListener('click', handler);
      el.style.opacity = '0';
      setTimeout(() => el.style.display = 'none', 500);
      resolve();
    };
    el.addEventListener('click', handler);
    el.addEventListener('touchstart', handler);
    btn.addEventListener('click', handler);
  });
}

boot();

export class WaveManager {
  constructor() {
    this._wave = 1;
    this._totalKilled = 0;
  }

  getWave() {
    return this._wave;
  }

  getMultiplier() {
    return this._wave;
  }

  getTotalKilled() {
    return this._totalKilled;
  }

  advanceWave() {
    this._wave++;
  }

  onInvaderKilled() {
    this._totalKilled++;
  }

  reset() {
    this._wave = 1;
    this._totalKilled = 0;
  }
}

export class ScoreSystem {
  constructor() {
    this._score = 0;
    this._combo = 0;
    this._multiplier = 1;
    this._lastKillTime = 0;
    this._totalKills = 0;
    this._totalShots = 0;
  }

  onShoot() {
    this._totalShots++;
  }

  onKill(currentTime) {
    this._totalKills++;
    const elapsed = (currentTime - this._lastKillTime) / 1000;
    if (elapsed < 1.5 && this._combo < 5) {
      this._combo++;
      this._multiplier = this._combo;
    } else if (elapsed >= 1.5) {
      this._combo = 0;
      this._multiplier = 1;
    }
    this._lastKillTime = currentTime;
    return this._multiplier;
  }

  add(points, _multiplier) {
    this._score += points;
  }

  getScore() { return this._score; }
  getCombo() { return this._combo; }
  getMultiplier() { return this._multiplier; }
  getTotalKills() { return this._totalKills; }
  getTotalShots() { return this._totalShots; }
  getAccuracy() {
    if (this._totalShots === 0) return 100;
    return Math.round((this._totalKills / this._totalShots) * 100);
  }

  onWaveClear() {
    // Reset combo between waves
    this._combo = 0;
    this._multiplier = 1;
  }

  reset() {
    this._score = 0;
    this._combo = 0;
    this._multiplier = 1;
    this._lastKillTime = 0;
    this._totalKills = 0;
    this._totalShots = 0;
  }
}

export class InputManager {
  constructor() {
    this.keys = {};
    this.prevKeys = {};
    this.gamepads = { axis: { horizontal: 0, vertical: 0 }, buttons: {} };
    this._boundOnKeyDown = this._onKeyDown.bind(this);
    this._boundOnKeyUp = this._onKeyUp.bind(this);
    window.addEventListener('keydown', this._boundOnKeyDown);
    window.addEventListener('keyup', this._boundOnKeyUp);
  }

  _onKeyDown(e) {
    this.keys[e.code] = true;
  }

  _onKeyUp(e) {
    this.keys[e.code] = false;
  }

  update() {
    this.prevKeys = { ...this.keys };
    const gp = navigator.getGamepads ? navigator.getGamepads()[0] : null;
    if (gp) {
      const deadzone = 0.15;
      const ax = gp.axes[0] || 0;
      const ay = gp.axes[1] || 0;
      this.gamepads.axis.horizontal = Math.abs(ax) > deadzone ? ax : 0;
      this.gamepads.axis.vertical = Math.abs(ay) > deadzone ? ay : 0;
      for (let i = 0; i < gp.buttons.length; i++) {
        this.gamepads.buttons[i] = gp.buttons[i].pressed;
      }
    }
  }

  getAxis(name) {
    let val = 0;
    if (name === 'horizontal') {
      if (this.keys['KeyA'] || this.keys['ArrowLeft']) val -= 1;
      if (this.keys['KeyD'] || this.keys['ArrowRight']) val += 1;
      const gp = this.gamepads.axis.horizontal;
      if (gp !== 0) val = gp;
    } else if (name === 'vertical') {
      if (this.keys['KeyW'] || this.keys['ArrowUp']) val += 1;
      if (this.keys['KeyS'] || this.keys['ArrowDown']) val -= 1;
      const gp = this.gamepads.axis.vertical;
      if (gp !== 0) val = gp;
    }
    return val;
  }

  getButton(name) {
    if (name === 'fire') {
      if (this.keys['Space']) return true;
      if (this.gamepads.buttons[0]) return true;
    }
    return false;
  }

  wasJustPressed(name) {
    if (name === 'fire') {
      const cur = this.keys['Space'] || false;
      const prev = this.prevKeys['Space'] || false;
      return cur && !prev;
    }
    return false;
  }

  dispose() {
    window.removeEventListener('keydown', this._boundOnKeyDown);
    window.removeEventListener('keyup', this._boundOnKeyUp);
  }
}

export class HitStop {
  constructor() {
    this._remaining = 0;
  }

  get isActive() {
    return this._remaining > 0;
  }

  trigger(ms) {
    this._remaining = Math.max(this._remaining, ms);
  }

  update() {
    if (this._remaining > 0) {
      this._remaining -= 16.67;
      if (this._remaining < 0) this._remaining = 0;
    }
  }

  getTimescale() {
    return this.isActive ? 0 : 1;
  }
}

import { clamp } from '../math/MathUtils.js';

export class CameraShake {
  constructor() {
    this._trauma = 0;
    this._offsetX = 0;
    this._offsetY = 0;
    this._offsetZ = 0;
  }

  addTrauma(amount) {
    this._trauma = Math.min(this._trauma + amount, 5.0);
  }

  update(dt, camera) {
    if (this._trauma < 0.001) {
      this._trauma = 0;
      this._offsetX = 0;
      this._offsetY = 0;
      this._offsetZ = 0;
      return;
    }
    const decay = 1 - 5.5 * dt;
    this._trauma *= Math.max(decay, 0);
    const spread = this._trauma * 0.4;
    this._offsetX = (Math.random() - 0.5) * 2 * spread;
    this._offsetY = (Math.random() - 0.5) * 2 * spread;
    this._offsetZ = (Math.random() - 0.5) * spread * 0.3;
    camera.position.x += this._offsetX;
    camera.position.y += this._offsetY;
    camera.position.z += this._offsetZ;
  }

  getIntensity() {
    return this._trauma;
  }

  reset() {
    this._trauma = 0;
    this._offsetX = 0;
    this._offsetY = 0;
    this._offsetZ = 0;
  }
}

import * as THREE from 'three';
import { clamp, randRange } from 'shared/math/MathUtils.js';

export class ParticleManager {
  constructor(scene, maxCount = 500) {
    this.scene = scene;
    this.maxCount = maxCount;
    this.activeCount = 0;

    // Particle data arrays (SoA for cache friendliness)
    this.positions = new Float32Array(maxCount * 3);
    this.velocities = new Float32Array(maxCount * 3);
    this.lifetimes = new Float32Array(maxCount); // remaining life in seconds
    this.maxLifetimes = new Float32Array(maxCount); // total lifetime for fade calc
    this.sizes = new Float32Array(maxCount);
    this.alive = new Uint8Array(maxCount); // 0 or 1

    // InstancedMesh for all particles
    const geometry = new THREE.SphereGeometry(0.08, 4, 4);
    const material = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0xffffff,
      emissiveIntensity: 2.0,
      toneMapped: false,
    });
    this.mesh = new THREE.InstancedMesh(geometry, material, maxCount);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);

    // Per-instance color
    this.colors = new Float32Array(maxCount * 3);
    const colorAttr = new THREE.InstancedBufferAttribute(this.colors, 3);
    colorAttr.setUsage(THREE.DynamicDrawUsage);
    this.mesh.instanceColor = colorAttr;

    this._dummy = new THREE.Object3D();
    this._tempColor = new THREE.Color();
    this._matrixArray = new Float32Array(maxCount * 16);

    scene.add(this.mesh);

    // Track for disposal
    this.geometry = geometry;
    this.material = material;
  }

  emit(config) {
    const {
      position, count, color, spread = 2, speedMin = 1, speedMax = 4,
      lifetimeMin = 0.3, lifetimeMax = 1.0, sizeMin = 0.05, sizeMax = 0.15,
      gravity = 0,
    } = config;

    let emitted = 0;
    const c = new THREE.Color(color);

    for (let i = 0; i < this.maxCount && emitted < count; i++) {
      if (this.alive[i]) continue;

      const i3 = i * 3;
      this.alive[i] = 1;
      this.positions[i3] = position.x;
      this.positions[i3 + 1] = position.y;
      this.positions[i3 + 2] = position.z;

      // Random velocity in a sphere
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const speed = randRange(speedMin, speedMax);
      this.velocities[i3] = Math.sin(phi) * Math.cos(theta) * speed;
      this.velocities[i3 + 1] = Math.sin(phi) * Math.sin(theta) * speed;
      this.velocities[i3 + 2] = Math.cos(phi) * speed;

      this.lifetimes[i] = randRange(lifetimeMin, lifetimeMax);
      this.maxLifetimes[i] = this.lifetimes[i];
      this.sizes[i] = randRange(sizeMin, sizeMax);

      // Color with slight variation
      const variation = 0.15;
      this.colors[i3] = clamp(c.r + randRange(-variation, variation), 0, 1);
      this.colors[i3 + 1] = clamp(c.g + randRange(-variation, variation), 0, 1);
      this.colors[i3 + 2] = clamp(c.b + randRange(-variation, variation), 0, 1);

      emitted++;
      this.activeCount++;
    }
    return emitted;
  }

  burst(position, count, color, spread = 2, speed = 3) {
    return this.emit({
      position, count, color, spread,
      speedMin: speed * 0.5, speedMax: speed * 1.5,
      lifetimeMin: 0.4, lifetimeMax: 1.0,
      sizeMin: 0.06, sizeMax: 0.14,
      gravity: -2,
    });
  }

  spark(position, count, color) {
    return this.emit({
      position, count, color,
      speedMin: 3, speedMax: 7,
      lifetimeMin: 0.15, lifetimeMax: 0.4,
      sizeMin: 0.03, sizeMax: 0.08,
      gravity: -4,
    });
  }

  explosion(position, count, color, radius = 3) {
    return this.emit({
      position, count, color,
      speedMin: radius * 0.5, speedMax: radius * 2,
      lifetimeMin: 0.5, lifetimeMax: 1.5,
      sizeMin: 0.08, sizeMax: 0.2,
      gravity: -1,
    });
  }

  update(dt) {
    let currentActive = 0;

    for (let i = 0; i < this.maxCount; i++) {
      if (!this.alive[i]) continue;

      this.lifetimes[i] -= dt;
      if (this.lifetimes[i] <= 0) {
        this.alive[i] = 0;
        // Hide instance by scaling to 0
        this._dummy.position.set(0, 0, 0);
        this._dummy.scale.set(0, 0, 0);
        this._dummy.updateMatrix();
        this.mesh.setMatrixAt(i, this._dummy.matrix);
        continue;
      }

      currentActive++;
      const i3 = i * 3;

      // Update velocity (gravity)
      this.velocities[i3 + 1] += -2 * dt; // default gravity

      // Update position
      this.positions[i3] += this.velocities[i3] * dt;
      this.positions[i3 + 1] += this.velocities[i3 + 1] * dt;
      this.positions[i3 + 2] += this.velocities[i3 + 2] * dt;

      // Fade and shrink
      const lifeRatio = this.lifetimes[i] / this.maxLifetimes[i];
      const scale = this.sizes[i] * lifeRatio;

      this._dummy.position.set(
        this.positions[i3],
        this.positions[i3 + 1],
        this.positions[i3 + 2]
      );
      this._dummy.scale.set(scale, scale, scale);
      this._dummy.updateMatrix();
      this.mesh.setMatrixAt(i, this._dummy.matrix);

      // Fade color
      this.colors[i3] *= 0.98;
      this.colors[i3 + 1] *= 0.98;
      this.colors[i3 + 2] *= 0.98;
    }

    this.activeCount = currentActive;
    this.mesh.instanceMatrix.needsUpdate = true;
    this.mesh.instanceColor.needsUpdate = true;
  }

  dispose() {
    this.scene.remove(this.mesh);
    this.mesh.geometry.dispose();
    this.mesh.material.dispose();
    this.mesh.dispose();
  }

  reset() {
    for (let i = 0; i < this.maxCount; i++) {
      this.alive[i] = 0;
      this.lifetimes[i] = 0;
      this._dummy.position.set(0, 0, 0);
      this._dummy.scale.set(0, 0, 0);
      this._dummy.updateMatrix();
      this.mesh.setMatrixAt(i, this._dummy.matrix);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
    this.activeCount = 0;
  }
}

import * as THREE from 'three';
import { clamp } from 'shared/math/MathUtils.js';
import { MemoryTracker } from 'shared/memory/MemoryTracker.js';

const tracker = new MemoryTracker();

export class MotionTrails {
  constructor(scene) {
    this.scene = scene;
    this.trails = new Map(); // mesh.uuid -> trail data
  }

  attach(mesh, length = 8, color = 0x00ffff, lineWidth = 2) {
    const uuid = mesh.uuid;
    if (this.trails.has(uuid)) return;

    const positions = new Float32Array(length * 3);
    const colors = new Float32Array(length * 3);
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    tracker.trackGeometry(geometry);

    const c = new THREE.Color(color);
    const material = new THREE.LineBasicMaterial({
      vertexColors: true,
      transparent: true,
      linewidth: lineWidth,
      depthWrite: false,
    });
    tracker.trackMaterial(material);

    const line = new THREE.Line(geometry, material);
    line.frustumCulled = false;
    this.scene.add(line);

    const history = [];
    for (let i = 0; i < length; i++) {
      history.push(new THREE.Vector3());
    }

    this.trails.set(uuid, { line, geometry, material, history, length, color: c, visible: false });
  }

  detach(mesh) {
    const uuid = mesh.uuid;
    const data = this.trails.get(uuid);
    if (!data) return;
    this.scene.remove(data.line);
    data.geometry.dispose();
    data.material.dispose();
    this.trails.delete(uuid);
  }

  update(dt) {
    for (const [uuid, data] of this.trails) {
      const mesh = this.scene.getObjectByProperty('uuid', uuid);
      if (!mesh || !mesh.visible) {
        data.visible = false;
        data.line.visible = false;
        continue;
      }

      data.visible = true;
      data.line.visible = true;

      // Shift history
      for (let i = data.history.length - 1; i > 0; i--) {
        data.history[i].copy(data.history[i - 1]);
      }
      mesh.getWorldPosition(data.history[0]);

      const posAttr = data.geometry.getAttribute('position');
      const colAttr = data.geometry.getAttribute('color');

      for (let i = 0; i < data.length; i++) {
        const p = data.history[i];
        posAttr.setXYZ(i, p.x, p.y, p.z);

        const alpha = 1.0 - (i / data.length);
        colAttr.setXYZ(i, data.color.r, data.color.g, data.color.b);
      }

      posAttr.needsUpdate = true;
      colAttr.needsUpdate = true;
    }
  }

  clear() {
    for (const [uuid, data] of this.trails) {
      this.scene.remove(data.line);
      data.geometry.dispose();
      data.material.dispose();
    }
    this.trails.clear();
  }
}

import * as THREE from 'three';
import { clamp } from 'shared/math/MathUtils';
import { MemoryTracker } from 'shared/memory/MemoryTracker';

const tracker = new MemoryTracker();

export class ShockwaveRings {
  constructor(scene) {
    this.scene = scene;
    this.rings = [];
  }

  emit(position, maxRadius, color, duration) {
    const radius = 0.05;
    const tube = 0.03;
    const radialSegments = 8;
    const tubularSegments = 32;
    const geometry = new THREE.TorusGeometry(radius, tube, radialSegments, tubularSegments);
    tracker.trackGeometry(geometry);
    const material = new THREE.MeshStandardMaterial({
      color: color || 0xffffff,
      emissive: color || 0xffffff,
      emissiveIntensity: 3,
      transparent: true,
      opacity: 1,
      depthWrite: false,
    });
    tracker.trackMaterial(material);
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.copy(position);
    mesh.rotation.x = Math.PI / 2;
    this.scene.add(mesh);
    this.rings.push({
      mesh,
      birth: performance.now(),
      duration: (duration || 600) / 1000,
      maxRadius: maxRadius || 2,
      disposed: false,
    });
  }

  update(dt) {
    const now = performance.now();
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const ring = this.rings[i];
      if (ring.disposed) { this.rings.splice(i, 1); continue; }
      const age = (now - ring.birth) / 1000;
      const t = clamp(age / ring.duration, 0, 1);
      const scale = 1 + t * ring.maxRadius * 15;
      ring.mesh.scale.set(scale, scale, 1);
      ring.mesh.material.opacity = 1 - t;
      ring.mesh.material.emissiveIntensity = 3 * (1 - t);
      if (t >= 1) {
        this.scene.remove(ring.mesh);
        ring.mesh.geometry.dispose();
        ring.mesh.material.dispose();
        this.rings.splice(i, 1);
      }
    }
  }

  clear() {
    for (const ring of this.rings) {
      if (!ring.disposed) {
        this.scene.remove(ring.mesh);
        ring.mesh.geometry.dispose();
        ring.mesh.material.dispose();
        ring.disposed = true;
      }
    }
    this.rings.length = 0;
  }
}

import * as THREE from 'three';
import { clamp } from '../math/MathUtils.js';
import { MemoryTracker } from '../memory/MemoryTracker.js';

export class FloatingText {
  constructor(scene) {
    this.scene = scene;
    this.items = [];
    this.tracker = new MemoryTracker();
  }

  show(position, text, color = '#ffffff', fontSize = 48, duration = 1.5) {
    const canvas = document.createElement('canvas');
    const size = 256;
    canvas.width = size;
    canvas.height = size / 2;
    const ctx = canvas.getContext('2d');

    ctx.fillStyle = 'rgba(0,0,0,0)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.font = `bold ${fontSize}px "Segoe UI", Arial, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // Glow
    ctx.shadowColor = color;
    ctx.shadowBlur = 16;
    ctx.fillStyle = color;
    ctx.fillText(text, canvas.width / 2, canvas.height / 2);

    // Core
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#ffffff';
    ctx.fillText(text, canvas.width / 2, canvas.height / 2);

    const texture = new THREE.CanvasTexture(canvas);
    texture.minFilter = THREE.LinearFilter;
    this.tracker.trackTexture(texture);

    const mat = new THREE.SpriteMaterial({
      map: texture,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    this.tracker.trackMaterial(mat);

    const sprite = new THREE.Sprite(mat);
    sprite.position.copy(position);
    sprite.scale.set(2.5, 1.25, 1);
    this.scene.add(sprite);

    this.items.push({
      sprite,
      material: mat,
      texture,
      birth: performance.now(),
      duration: duration * 1000,
      startY: position.y,
    });
  }

  update(dt) {
    const now = performance.now();
    for (let i = this.items.length - 1; i >= 0; i--) {
      const item = this.items[i];
      const elapsed = now - item.birth;
      const t = clamp(elapsed / item.duration, 0, 1);

      // Fade out in last 40%
      const alpha = t > 0.6 ? 1 - ((t - 0.6) / 0.4) : 1;
      item.material.opacity = alpha;

      // Float upward
      item.sprite.position.y = item.startY + t * 2.5;

      // Scale up slightly then shrink
      const scale = 1 + Math.sin(t * Math.PI) * 0.3;
      item.sprite.scale.set(2.5 * scale, 1.25 * scale, 1);

      if (t >= 1) {
        this.scene.remove(item.sprite);
        item.material.map.dispose();
        item.material.dispose();
        this.items.splice(i, 1);
      }
    }
  }

  clear() {
    for (const item of this.items) {
      this.scene.remove(item.sprite);
      item.material.map.dispose();
      item.material.dispose();
    }
    this.items.length = 0;
  }

  dispose() {
    this.clear();
    this.tracker.disposeAll();
  }
}

import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { Vector2 } from 'three';

export function createComposer(renderer, width, height, bloomConfig = {}) {
  const composer = new EffectComposer(renderer);

  const renderPass = new RenderPass();
  composer.addPass(renderPass);

  const {
    strength = 0.6,
    radius = 0.4,
    threshold = 0.85,
  } = bloomConfig;

  const bloomPass = new UnrealBloomPass(
    new Vector2(width, height),
    strength,
    radius,
    threshold
  );
  composer.addPass(bloomPass);

  composer.setSize(width, height);

  return { composer, renderPass, bloomPass };
}

/**
 * AudioManager — Web Audio API synthesized SFX and procedural music bed.
 * No external audio files. All sounds generated via oscillators and noise buffers.
 */

const SFX_DEFS = {
  playerShoot:   { type: 'square', freq: 880, duration: 0.08, decay: 0.06, vol: 0.25 },
  invaderShoot:  { type: 'sawtooth', freq: 150, duration: 0.15, decay: 0.12, vol: 0.15 },
  invaderKill:   { type: 'noise', duration: 0.25, vol: 0.3 },
  playerHit:     { type: 'rumble', duration: 0.4, vol: 0.35 },
  mysteryKill:   { type: 'arpeggio', duration: 0.6, vol: 0.3 },
  shieldErode:   { type: 'click', duration: 0.05, vol: 0.15 },
  waveClear:     { type: 'fanfare', duration: 0.8, vol: 0.3 },
  gameOver:      { type: 'descend', duration: 1.2, vol: 0.35 },
  invaderStep:   { type: 'tick', duration: 0.03, vol: 0.1 },
  mysteryAppear: { type: 'warble', duration: 0.5, vol: 0.2 },
};

export class AudioManager {
  constructor() {
    this.ctx = null;
    this.masterGain = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.musicPlaying = false;
    this.musicNodes = [];
    this.waveNumber = 1;
    this.volume = 0.3;
  }

  init() {
    if (this.ctx) return;
    this.ctx = new (window.AudioContext || window.webkitAudioContext)();
    this.masterGain = this.ctx.createGain();
    this.masterGain.gain.value = this.volume;
    this.masterGain.connect(this.ctx.destination);

    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.5;
    this.musicGain.connect(this.masterGain);

    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 1.0;
    this.sfxGain.connect(this.masterGain);
  }

  setVolume(v) {
    this.volume = Math.max(0, Math.min(1, v));
    if (this.masterGain) this.masterGain.gain.value = this.volume;
  }

  setWave(w) {
    this.waveNumber = w;
  }

  // --- SFX ---

  playSFX(type, pitch = 1.0) {
    if (!this.ctx) this.init();
    if (this.ctx.state === 'suspended') this.ctx.resume();
    const def = SFX_DEFS[type];
    if (!def) return;
    const t = this.ctx.currentTime;

    switch (def.type) {
      case 'square':
      case 'sawtooth': {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        osc.type = def.type;
        osc.frequency.value = def.freq * pitch;
        gain.gain.setValueAtTime(def.vol, t);
        gain.gain.exponentialRampToValueAtTime(0.001, t + def.duration);
        osc.connect(gain);
        gain.connect(this.sfxGain);
        osc.start(t);
        osc.stop(t + def.duration);
        break;
      }
      case 'noise': {
        const bufferSize = this.ctx.sampleRate * def.duration;
        const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1);
        const source = this.ctx.createBufferSource();
        source.buffer = buffer;
        const gain = this.ctx.createGain();
        gain.gain.setValueAtTime(def.vol, t);
        gain.gain.exponentialRampToValueAtTime(0.001, t + def.duration);
        const filter = this.ctx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(3000 * pitch, t);
        filter.frequency.exponentialRampToValueAtTime(200, t + def.duration);
        source.connect(filter);
        filter.connect(gain);
        gain.connect(this.sfxGain);
        source.start(t);
        break;
      }
      case 'rumble': {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        osc.type = 'sine';
        osc.frequency.value = 60;
        gain.gain.setValueAtTime(def.vol, t);
        gain.gain.exponentialRampToValueAtTime(0.001, t + def.duration);
        osc.connect(gain);
        gain.connect(this.sfxGain);
        osc.start(t);
        osc.stop(t + def.duration);
        // Add noise layer
        const bufSize = this.ctx.sampleRate * def.duration;
        const buf = this.ctx.createBuffer(1, bufSize, this.ctx.sampleRate);
        const d = buf.getChannelData(0);
        for (let i = 0; i < bufSize; i++) d[i] = Math.random() * 2 - 1;
        const ns = this.ctx.createBufferSource();
        ns.buffer = buf;
        const ng = this.ctx.createGain();
        ng.gain.setValueAtTime(def.vol * 0.5, t);
        ng.gain.exponentialRampToValueAtTime(0.001, t + def.duration * 0.7);
        const nf = this.ctx.createBiquadFilter();
        nf.type = 'lowpass';
        nf.frequency.value = 300;
        ns.connect(nf);
        nf.connect(ng);
        ng.connect(this.sfxGain);
        ns.start(t);
        break;
      }
      case 'arpeggio': {
        const notes = [261.63, 329.63, 392.00, 523.25, 659.25];
        const noteLen = def.duration / notes.length;
        notes.forEach((freq, i) => {
          const osc = this.ctx.createOscillator();
          const gain = this.ctx.createGain();
          osc.type = 'square';
          osc.frequency.value = freq * pitch;
          gain.gain.setValueAtTime(0, t + i * noteLen);
          gain.gain.linearRampToValueAtTime(def.vol * 0.4, t + i * noteLen + 0.02);
          gain.gain.exponentialRampToValueAtTime(0.001, t + i * noteLen + noteLen);
          osc.connect(gain);
          gain.connect(this.sfxGain);
          osc.start(t + i * noteLen);
          osc.stop(t + i * noteLen + noteLen + 0.05);
        });
        break;
      }
      case 'click': {
        const bufSize = this.ctx.sampleRate * def.duration;
        const buf = this.ctx.createBuffer(1, bufSize, this.ctx.sampleRate);
        const d = buf.getChannelData(0);
        for (let i = 0; i < bufSize; i++) d[i] = Math.random() * 2 - 1;
        const source = this.ctx.createBufferSource();
        source.buffer = buf;
        const gain = this.ctx.createGain();
        gain.gain.setValueAtTime(def.vol, t);
        gain.gain.exponentialRampToValueAtTime(0.001, t + def.duration);
        const f = this.ctx.createBiquadFilter();
        f.type = 'highpass';
        f.frequency.value = 4000;
        source.connect(f);
        f.connect(gain);
        gain.connect(this.sfxGain);
        source.start(t);
        break;
      }
      case 'fanfare': {
        const notes = [261.63, 329.63, 392.00, 523.25, 659.25, 783.99, 1046.50];
        const noteLen = def.duration / notes.length;
        notes.forEach((freq, i) => {
          const osc = this.ctx.createOscillator();
          const gain = this.ctx.createGain();
          osc.type = 'triangle';
          osc.frequency.value = freq;
          gain.gain.setValueAtTime(0, t + i * noteLen);
          gain.gain.linearRampToValueAtTime(def.vol * 0.3, t + i * noteLen + 0.02);
          gain.gain.exponentialRampToValueAtTime(0.001, t + i * noteLen + noteLen * 0.9);
          osc.connect(gain);
          gain.connect(this.sfxGain);
          osc.start(t + i * noteLen);
          osc.stop(t + i * noteLen + noteLen + 0.05);
        });
        break;
      }
      case 'descend': {
        const notes = [523.25, 493.88, 440.00, 392.00, 349.23, 329.63, 293.66, 261.63];
        const noteLen = def.duration / notes.length;
        notes.forEach((freq, i) => {
          const osc = this.ctx.createOscillator();
          const gain = this.ctx.createGain();
          osc.type = 'sawtooth';
          osc.frequency.value = freq;
          gain.gain.setValueAtTime(0, t + i * noteLen);
          gain.gain.linearRampToValueAtTime(def.vol * 0.25, t + i * noteLen + 0.02);
          gain.gain.exponentialRampToValueAtTime(0.001, t + i * noteLen + noteLen * 0.9);
          osc.connect(gain);
          gain.connect(this.sfxGain);
          osc.start(t + i * noteLen);
          osc.stop(t + i * noteLen + noteLen + 0.05);
        });
        break;
      }
      case 'tick': {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        osc.type = 'square';
        osc.frequency.value = 1200 * pitch;
        gain.gain.setValueAtTime(def.vol, t);
        gain.gain.exponentialRampToValueAtTime(0.001, t + def.duration);
        osc.connect(gain);
        gain.connect(this.sfxGain);
        osc.start(t);
        osc.stop(t + def.duration + 0.01);
        break;
      }
      case 'warble': {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        const lfo = this.ctx.createOscillator();
        const lfoGain = this.ctx.createGain();
        osc.type = 'sine';
        osc.frequency.value = 440;
        lfo.type = 'sine';
        lfo.frequency.value = 8;
        lfoGain.gain.value = 100;
        lfo.connect(lfoGain);
        lfoGain.connect(osc.frequency);
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(def.vol, t + 0.1);
        gain.gain.setValueAtTime(def.vol, t + def.duration * 0.7);
        gain.gain.linearRampToValueAtTime(0.001, t + def.duration);
        osc.connect(gain);
        gain.connect(this.sfxGain);
        osc.start(t);
        lfo.start(t);
        osc.stop(t + def.duration + 0.05);
        lfo.stop(t + def.duration + 0.05);
        break;
      }
    }
  }

  // --- Music Bed ---

  startMusic() {
    if (!this.ctx) this.init();
    if (this.ctx.state === 'suspended') this.ctx.resume();
    if (this.musicPlaying) return;
    this.musicPlaying = true;
    this._scheduleMusic();
  }

  stopMusic() {
    this.musicPlaying = false;
    this.musicNodes.forEach(node => {
      try { node.stop(); } catch (_) {}
      try { node.disconnect(); } catch (_) {}
    });
    this.musicNodes = [];
  }

  _scheduleMusic() {
    if (!this.musicPlaying || !this.ctx) return;
    const t = this.ctx.currentTime;
    const bpm = 120 + (this.waveNumber - 1) * 10;
    const beatDur = 60 / bpm;
    const loopBeats = 16;
    const loopDur = loopBeats * beatDur;

    // Bass drone
    const drone = this.ctx.createOscillator();
    const droneGain = this.ctx.createGain();
    const droneFilter = this.ctx.createBiquadFilter();
    drone.type = 'sine';
    drone.frequency.value = 55;
    droneFilter.type = 'lowpass';
    droneFilter.frequency.value = 120;
    droneGain.gain.setValueAtTime(0.15, t);
    droneGain.gain.setValueAtTime(0.15, t + loopDur - 0.1);
    droneGain.gain.linearRampToValueAtTime(0, t + loopDur);
    drone.connect(droneFilter);
    droneFilter.connect(droneGain);
    droneGain.connect(this.musicGain);
    drone.start(t);
    drone.stop(t + loopDur);
    this.musicNodes.push(drone);

    // Arpeggio — phrygian mode
    const phrygian = [130.81, 146.83, 164.81, 174.61, 196.00, 220.00, 246.94];
    for (let i = 0; i < loopBeats; i++) {
      const noteTime = t + i * beatDur;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'square';
      const noteIdx = i % phrygian.length;
      const octave = i < 8 ? 1 : 2;
      osc.frequency.value = phrygian[noteIdx] * octave;
      gain.gain.setValueAtTime(0.06, noteTime);
      gain.gain.exponentialRampToValueAtTime(0.001, noteTime + beatDur * 0.8);
      osc.connect(gain);
      gain.connect(this.musicGain);
      osc.start(noteTime);
      osc.stop(noteTime + beatDur);
      this.musicNodes.push(osc);
    }

    // Hi-hat on every other beat
    for (let i = 0; i < loopBeats; i += 2) {
      const noteTime = t + i * beatDur;
      const bufSize = this.ctx.sampleRate * beatDur * 0.3;
      const buf = this.ctx.createBuffer(1, bufSize, this.ctx.sampleRate);
      const d = buf.getChannelData(0);
      for (let j = 0; j < bufSize; j++) d[j] = Math.random() * 2 - 1;
      const src = this.ctx.createBufferSource();
      src.buffer = buf;
      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(0.04, noteTime);
      gain.gain.exponentialRampToValueAtTime(0.001, noteTime + beatDur * 0.3);
      const f = this.ctx.createBiquadFilter();
      f.type = 'highpass';
      f.frequency.value = 8000;
      src.connect(f);
      f.connect(gain);
      gain.connect(this.musicGain);
      src.start(noteTime);
    }

    // Schedule next loop
    setTimeout(() => this._scheduleMusic(), loopDur * 1000 - 100);
  }
}

export class MemoryTracker {
  constructor() {
    this._geometries = new Set();
    this._materials = new Set();
    this._textures = new Set();
  }
  trackGeometry(geo) { if (geo) this._geometries.add(geo); }
  trackMaterial(mat) { if (mat) this._materials.add(mat); }
  trackTexture(tex) { if (tex) this._textures.add(tex); }
  disposeAll() {
    for (const g of this._geometries) g.dispose();
    for (const m of this._materials) m.dispose();
    for (const t of this._textures) t.dispose();
    this._geometries.clear();
    this._materials.clear();
    this._textures.clear();
  }
}

// Singleton for modules that don't need per-instance tracking
export const tracker = new MemoryTracker();

import * as THREE from 'three';
import { Game } from './Space_Invaders/Game.js';

let gameInstance = null;

async function boot() {
  await waitForAudio();

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.0;
  document.getElementById('canvas-container').appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050510);
  scene.fog = new THREE.FogExp2(0x050510, 0.015);

  const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 100);
  camera.position.set(0, 0, 14);
  camera.lookAt(0, 0, 0);

  const { createComposer } = await import('shared/rendering/EffectComposerSetup.js');
  const { composer } = createComposer(renderer, window.innerWidth, window.innerHeight, {
    strength: 0.6, radius: 0.4, threshold: 0.85,
  });

  const { InputManager } = await import('shared/input/InputManager.js');
  const { ParticleManager } = await import('shared/vfx/ParticleManager.js');
  const { CameraShake } = await import('shared/vfx/CameraShake.js');
  const { HitStop } = await import('shared/vfx/HitStop.js');
  const { MotionTrails } = await import('shared/vfx/MotionTrails.js');
  const { ShockwaveRings } = await import('shared/vfx/ShockwaveRings.js');
  const { FloatingText } = await import('shared/vfx/FloatingText.js');
  const { AudioManager } = await import('shared/audio/AudioManager.js');

  const input = new InputManager();
  const particles = new ParticleManager(scene, 500);
  const cameraShake = new CameraShake();
  const hitStop = new HitStop();
  const motionTrails = new MotionTrails(scene);
  const shockwaves = new ShockwaveRings(scene);
  const floatingText = new FloatingText(scene);
  const audio = new AudioManager();

  audio.init();
  audio.setVolume(0.3);

  gameInstance = new Game(scene, camera, composer, input, {
    particles,
    shake: cameraShake,
    hitStop,
    trails: motionTrails,
    shockwaves,
    floatingText,
  }, audio);

  gameInstance.init();

  window.addEventListener('resize', () => {
    const w = window.innerWidth, h = window.innerHeight;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
    composer.setSize(w, h);
  });

  const clock = new THREE.Clock();
  function loop() {
    requestAnimationFrame(loop);
    const rawDt = Math.min(clock.getDelta(), 0.05);
    input.update();
    hitStop.update();
    const timescale = hitStop.getTimescale();
    const dt = timescale > 0 ? rawDt : 0;
    gameInstance.update(dt);
    composer.render();
  }
  loop();
}

function waitForAudio() {
  return new Promise((resolve) => {
    const el = document.getElementById('start-overlay');
    const btn = document.getElementById('btn-start');
    const handler = () => {
      el.removeEventListener('click', handler);
      el.removeEventListener('touchstart', handler);
      btn.removeEventListener('click', handler);
      el.style.opacity = '0';
      setTimeout(() => el.style.display = 'none', 500);
      resolve();
    };
    el.addEventListener('click', handler);
    el.addEventListener('touchstart', handler);
    btn.addEventListener('click', handler);
  });
}

boot();

import * as THREE from 'three';
import { Player } from './Player.js';
import { InvaderGrid } from './InvaderGrid.js';
import { Shields } from './Shields.js';
import { ProjectileSystem } from './ProjectileSystem.js';
import { MysteryShip } from './MysteryShip.js';
import { WaveManager } from './WaveManager.js';
import { ScoreSystem } from './ScoreSystem.js';
import { CollisionSystem } from './CollisionSystem.js';
import { Background } from './Background.js';
import { HUD } from './HUD.js';
import { MemoryTracker } from 'shared/memory/MemoryTracker.js';
import { CONFIG } from './config.js';

export class Game {
  constructor(scene, camera, composer, input, vfx, audio) {
    this.scene = scene;
    this.camera = camera;
    this.composer = composer;
    this.input = input;
    this.vfx = vfx;
    this.audio = audio;

    this.tracker = new MemoryTracker();
    this.state = 'menu';
    this.waveClearTimer = 0;
    this.gameOverTimer = 0;

    // Subsystems
    this.player = null;
    this.invaderGrid = null;
    this.shields = null;
    this.projectiles = null;
    this.mysteryShip = null;
    this.waveManager = null;
    this.scoreSystem = null;
    this.collisions = null;
    this.background = null;
    this.hud = null;

    // Lighting
    this.orbitLight1 = null;
    this.orbitLight2 = null;
    this.playerLight = null;
    this.flashLight = null;
    this.orbitAngle = 0;

    // Screen flash
    this.flashOverlay = null;
    this.flashAlpha = 0;

    // Thruster timer
    this.thrusterTimer = 0;
  }

  init() {
    // Clear scene
    while (this.scene.children.length > 0) {
      this.scene.remove(this.scene.children[0]);
    }
    this.tracker.disposeAll();

    // Ambient light
    const ambient = new THREE.AmbientLight(0x334455, 0.4);
    this.scene.add(ambient);

    // Orbiting lights
    this.orbitLight1 = new THREE.PointLight(0x00ffff, 2, 30);
    this.orbitLight1.position.set(5, 5, 5);
    this.scene.add(this.orbitLight1);

    this.orbitLight2 = new THREE.PointLight(0xff00ff, 2, 30);
    this.orbitLight2.position.set(-5, -5, 5);
    this.scene.add(this.orbitLight2);

    // Player attached light
    this.playerLight = new THREE.PointLight(0x0088ff, 1.5, 8);
    this.scene.add(this.playerLight);

    // Flash light for explosions
    this.flashLight = new THREE.PointLight(0xffffff, 0, 20);
    this.scene.add(this.flashLight);

    // Screen flash overlay
    this.flashOverlay = document.getElementById('screen-flash');
    this.flashAlpha = 0;

    // Background
    this.background = new Background(this.scene, this.tracker);
    this.background.init();

    // Player
    this.player = new Player(this.scene, this.tracker);
    this.player.init();

    // Invader grid
    this.invaderGrid = new InvaderGrid(this.scene, this.tracker);
    this.invaderGrid.init(1);

    // Shields
    this.shields = new Shields(this.scene, this.tracker);
    this.shields.init();

    // Projectiles
    this.projectiles = new ProjectileSystem(this.scene, this.tracker);
    this.projectiles.init();

    // Mystery ship
    this.mysteryShip = new MysteryShip(this.scene, this.tracker);
    this.mysteryShip.init();

    // Wave manager
    this.waveManager = new WaveManager();

    // Score system
    this.scoreSystem = new ScoreSystem();

    // Collision system
    this.collisions = new CollisionSystem();

    // HUD
    this.hud = new HUD();
    this.hud.init();

    // Start music
    this.audio.startMusic();

    this.state = 'playing';
  }

  startWave(waveNum) {
    this.invaderGrid.reset(waveNum);
    this.shields.reset();
    this.projectiles.clear();
    this.mysteryShip.despawn();
    this.waveManager.advanceWave();
    this.scoreSystem.onWaveClear();
    this.audio.setWave(waveNum);
  }

  update(dt) {
    if (this.state === 'menu') {
      if (this.input.wasJustPressed('fire')) {
        this.init();
      }
      return;
    }

    if (this.state === 'gameOver') {
      this.gameOverTimer += dt;
      this.vfx.particles.update(dt);
      this.vfx.shockwaves.update(dt);
      this.vfx.floatingText.update(dt);
      this.background.update(dt);
      this.updateOrbitLights(dt);
      if (this.input.wasJustPressed('fire') && this.gameOverTimer > 2) {
        this.gameOverTimer = 0;
        this.init();
      }
      return;
    }

    if (this.state === 'waveClear') {
      this.waveClearTimer += dt;
      this.vfx.particles.update(dt);
      this.vfx.shockwaves.update(dt);
      this.vfx.floatingText.update(dt);
      this.background.update(dt);
      this.updateOrbitLights(dt);
      if (this.waveClearTimer > 3) {
        this.state = 'playing';
        this.startWave(this.waveManager.getWave() + 1);
      }
      return;
    }

    // Hit-stop check
    const timescale = this.vfx.hitStop.getTimescale();
    const gameDt = dt * timescale;

    // Update orbiting lights
    this.updateOrbitLights(dt);

    // Player light follows ship
    this.playerLight.position.copy(this.player.group.position);
    this.playerLight.position.z += 2;

    // Player update
    this.player.update(gameDt, this.input);

    // Player firing
    const firePos = this.player.fire();
    if (firePos) {
      this.projectiles.firePlayer(firePos);
      this.audio.playSFX('playerShoot');
    }

    // Thruster particles
    this.thrusterTimer += dt;
    if (this.thrusterTimer > 0.05) {
      this.thrusterTimer = 0;
      const count = Math.abs(this.input.getAxis('horizontal')) > 0.1 ? 3 : 1;
      this.vfx.particles.burst(
        this.player.group.position.clone(),
        count,
        0x0088ff,
        0.3,
        1.5
      );
    }

    // Invader grid update
    this.invaderGrid.update(gameDt);

    // Invader firing
    const invaderFirePos = this.invaderGrid.fire(gameDt);
    if (invaderFirePos) {
      this.projectiles.fireInvader(invaderFirePos);
      this.audio.playSFX('invaderShoot');
    }

    // Projectile update
    this.projectiles.update(gameDt);

    // Mystery ship update
    this.mysteryShip.update(gameDt);

    // Collision detection
    this.resolveCollisions();

    // Check wave clear
    if (this.invaderGrid.getAlive().length === 0 && this.state === 'playing') {
      this.onWaveClear();
    }

    // Check invader descent
    if (this.invaderGrid.checkDescent() && this.state === 'playing') {
      this.onGameOver();
    }

    // Update HUD
    this.hud.update(
      this.scoreSystem.getScore(),
      this.waveManager.getWave(),
      this.player.hp,
      CONFIG.PLAYER_MAX_HP,
      this.scoreSystem.getCombo(),
      this.scoreSystem.getMultiplier()
    );

    // Update VFX
    this.vfx.particles.update(dt);
    this.vfx.shake.update(dt, this.camera);
    this.vfx.trails.update(dt);
    this.vfx.shockwaves.update(dt);
    this.vfx.floatingText.update(dt);
    this.background.update(dt);

    // Screen flash decay
    if (this.flashAlpha > 0) {
      this.flashAlpha -= dt * 3;
      if (this.flashAlpha < 0) this.flashAlpha = 0;
      if (this.flashOverlay) {
        this.flashOverlay.style.opacity = this.flashAlpha;
      }
    }
  }

  updateOrbitLights(dt) {
    this.orbitAngle += dt * 0.3;
    const r = 10;
    this.orbitLight1.position.x = Math.cos(this.orbitAngle) * r;
    this.orbitLight1.position.y = Math.sin(this.orbitAngle * 0.7) * r * 0.5;
    this.orbitLight2.position.x = Math.cos(this.orbitAngle + Math.PI) * r;
    this.orbitLight2.position.y = Math.sin(this.orbitAngle * 0.7 + Math.PI) * r * 0.5;
  }

  resolveCollisions() {
    const playerProjPos = this.projectiles.getPlayerProjPos();
    const invaderProjPositions = this.projectiles.getInvaderProjPositions();
    const aliveInvaders = this.invaderGrid.getAlive();
    const invaderBounds = aliveInvaders.map(inv => inv.getBounds());

    // Shield erosion callback
    const shieldErode = (pos, radius) => {
      this.shields.erode(pos, radius);
    };

    // Player projectile vs invaders
    if (playerProjPos) {
      const hit = this.collisions.checkPlayerProjectile(
        playerProjPos,
        invaderBounds,
        aliveInvaders,
        shieldErode
      );
      if (hit) {
        this.onInvaderKilled(hit.invader, hit.index);
        this.projectiles.removePlayerProjectile();
      } else {
        // Check vs mystery ship
        if (this.mysteryShip.isAlive) {
          const msHit = this.collisions.checkMysteryShip(playerProjPos, this.mysteryShip.getBounds());
          if (msHit) {
            this.onMysteryShipKilled();
            this.projectiles.removePlayerProjectile();
          }
        }
      }

      // Player projectile vs shields
      this.collisions.checkProjectileVsShields(playerProjPos, shieldErode);
      if (this.collisions.shieldHit) {
        this.projectiles.removePlayerProjectile();
        this.collisions.shieldHit = false;
      }
    }

    // Invader projectiles vs player
    for (let i = invaderProjPositions.length - 1; i >= 0; i--) {
      const projPos = invaderProjPositions[i];
      // vs shields first
      this.collisions.checkProjectileVsShields(projPos, shieldErode);
      if (this.collisions.shieldHit) {
        this.projectiles.removeInvaderProjectile(i);
        this.collisions.shieldHit = false;
        continue;
      }
      // vs player
      if (this.collisions.checkInvaderProjectile(projPos, this.player.getBounds())) {
        this.onPlayerHit();
        this.projectiles.removeInvaderProjectile(i);
      }
    }

    // Player vs invaders (body collision)
    if (this.collisions.checkInvaderDescent(invaderBounds, this.player.getBounds())) {
      this.onPlayerHit();
    }
  }

  onInvaderKilled(invader, index) {
    const basePoints = invader.points;
    const waveMult = this.waveManager.getMultiplier();
    const comboMult = this.scoreSystem.onKill(performance.now());
    const totalPoints = basePoints * waveMult * comboMult;

    this.scoreSystem.add(totalPoints, comboMult);

    // VFX
    const pos = invader.mesh.position.clone();
    const color = invader.emissiveColor;

    // Hit-stop (light)
    this.vfx.hitStop.trigger(60);

    // Camera shake
    this.vfx.shake.addTrauma(0.3);

    // Flash light
    this.flashLight.position.copy(pos);
    this.flashLight.intensity = 5;
    setTimeout(() => { this.flashLight.intensity = 0; }, 100);

    // Particle burst
    this.vfx.particles.burst(pos, 30, color, 1.5, 4);

    // Shockwave ring
    this.vfx.shockwaves.emit(pos, 2.0, color, 0.6);

    // Floating score text
    this.vfx.floatingText.show(pos, `+${totalPoints}`, color, 24, 1.2);

    // Audio
    this.audio.playSFX('invaderKill', 1.0 + (5 - invader.row) * 0.15);

    // Remove invader
    invader.die();
    this.waveManager.onInvaderKilled();
  }

  onPlayerHit() {
    this.player.takeDamage();

    // VFX
    const pos = this.player.group.position.clone();

    // Hit-stop (heavy)
    this.vfx.hitStop.trigger(120);

    // Camera shake
    this.vfx.shake.addTrauma(0.8);

    // Particles
    this.vfx.particles.burst(pos, 20, 0xffffff, 0.8, 3);

    // Audio
    this.audio.playSFX('playerHit');

    // Flash player ship
    this.player.flashHit();

    // Check death
    if (this.player.hp <= 0) {
      this.onGameOver();
    }
  }

  onMysteryShipKilled() {
    const points = this.mysteryShip.points;
    const waveMult = this.waveManager.getMultiplier();
    const totalPoints = points * waveMult;

    this.scoreSystem.add(totalPoints, 1);

    const pos = this.mysteryShip.mesh.position.clone();

    // Hit-stop (dramatic)
    this.vfx.hitStop.trigger(200);

    // Camera shake (heavy)
    this.vfx.shake.addTrauma(1.5);

    // Screen flash
    this.flashAlpha = 0.6;

    // Particles
    this.vfx.particles.burst(pos, 80, 0xff00ff, 3, 6);

    // Shockwave rings (2 staggered)
    this.vfx.shockwaves.emit(pos, 4.0, 0xff00ff, 0.8);
    setTimeout(() => {
      this.vfx.shockwaves.emit(pos, 3.0, 0xffffff, 0.6);
    }, 100);

    // Floating text
    this.vfx.floatingText.show(pos, `+${totalPoints}`, 0xffd700, 36, 2);

    // Audio
    this.audio.playSFX('mysteryKill');

    // Despawn
    this.mysteryShip.despawn();
  }

  onWaveClear() {
    this.state = 'waveClear';
    this.waveClearTimer = 0;

    // VFX
    this.vfx.hitStop.trigger(300);
    this.vfx.shake.addTrauma(0.5);

    // Celebration particles
    for (let i = 0; i < 5; i++) {
      const x = (Math.random() - 0.5) * 10;
      const y = (Math.random() - 0.5) * 6;
      const z = 0;
      const color = [0xff0000, 0x00ff00, 0x0000ff, 0xffff00, 0xff00ff][i];
      this.vfx.particles.burst(new THREE.Vector3(x, y, z), 20, color, 2, 5);
    }

    // Floating text
    this.vfx.floatingText.show(
      new THREE.Vector3(0, 2, 0),
      `WAVE ${this.waveManager.getWave()} COMPLETE`,
      0xffd700,
      32,
      2.5
    );

    // HUD
    this.hud.showWaveComplete(this.waveManager.getWave());

    // Audio
    this.audio.playSFX('waveClear');
  }

  onGameOver() {
    this.state = 'gameOver';
    this.gameOverTimer = 0;

    // Audio
    this.audio.playSFX('gameOver');
    this.audio.stopMusic();

    // VFX
    this.vfx.hitStop.trigger(400);
    this.vfx.shake.addTrauma(1.2);

    // Big explosion at player position
    this.vfx.particles.burst(
      this.player.group.position.clone(),
      60,
      0xff4444,
      2,
      5
    );

    // HUD
    const stats = {
      score: this.scoreSystem.getScore(),
      wave: this.waveManager.getWave(),
      invadersKilled: this.waveManager.getTotalKilled(),
      accuracy: 0 // simplified
    };
    this.hud.showGameOver(stats);
  }

  dispose() {
    this.tracker.disposeAll();
    if (this.hud) this.hud.dispose();
    this.audio.stopMusic();
  }
}

import { clamp } from 'shared/math/MathUtils.js';

export class CollisionSystem {
  constructor() {
    this.shieldHit = false;
  }

  /**
   * Check player projectile against all invader bounds.
   * Returns { hit: true, invader, index } or { hit: false }.
   */
  checkPlayerProjectile(projPos, invaderBounds, aliveInvaders, shieldErodeFn) {
    // Check against each invader
    for (let i = 0; i < invaderBounds.length; i++) {
      const b = invaderBounds[i];
      if (!b) continue;
      if (this._pointInAABB(projPos.x, projPos.y, b)) {
        return { hit: true, invader: aliveInvaders[i], index: i };
      }
    }
    return { hit: false };
  }

  /**
   * Check invader projectile against player bounds.
   */
  checkInvaderProjectile(projPos, playerBounds) {
    return this._pointInAABB(projPos.x, projPos.y, playerBounds);
  }

  /**
   * Check player projectile against mystery ship bounds.
   */
  checkMysteryShip(projPos, shipBounds) {
    if (!shipBounds) return false;
    return this._pointInAABB(projPos.x, projPos.y, shipBounds);
  }

  /**
   * Check if projectile hit any shield.
   */
  checkProjectileVsShields(projPos, shieldErodeFn) {
    this.shieldHit = false;
    const hit = shieldErodeFn(projPos, 0.4);
    if (hit) this.shieldHit = true;
  }

  /**
   * Check if any invader has descended below threshold (body collision with player).
   */
  checkInvaderDescent(invaderBounds, playerBounds) {
    for (const b of invaderBounds) {
      if (!b) continue;
      if (b.minY <= playerBounds.maxY && b.maxY >= playerBounds.minY) {
        if (b.maxX >= playerBounds.minX && b.minX <= playerBounds.maxX) {
          return true;
        }
      }
    }
    return false;
  }

  _pointInAABB(px, py, b) {
    return px >= b.minX && px <= b.maxX && py >= b.minY && py <= b.maxY;
  }
}

import * as THREE from 'three';
import { clamp } from 'shared/math/MathUtils.js';
import { MemoryTracker } from 'shared/memory/MemoryTracker.js';

const tracker = new MemoryTracker();

export class ShockwaveRings {
  constructor(scene) {
    this.scene = scene;
    this.rings = [];
  }

  emit(position, maxRadius, color, duration) {
    const radius = 0.05;
    const tube = 0.03;
    const radialSegments = 8;
    const tubularSegments = 32;
    const geometry = new THREE.TorusGeometry(radius, tube, radialSegments, tubularSegments);
    tracker.trackGeometry(geometry);
    const material = new THREE.MeshStandardMaterial({
      color: color || 0xffffff,
      emissive: color || 0xffffff,
      emissiveIntensity: 3,
      transparent: true,
      opacity: 1,
      depthWrite: false,
    });
    tracker.trackMaterial(material);
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.copy(position);
    mesh.rotation.x = Math.PI / 2;
    this.scene.add(mesh);
    this.rings.push({
      mesh,
      birth: performance.now(),
      duration: (duration || 600) / 1000,
      maxRadius: maxRadius || 2,
      disposed: false,
    });
  }

  update(dt) {
    const now = performance.now();
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const ring = this.rings[i];
      if (ring.disposed) { this.rings.splice(i, 1); continue; }
      const age = (now - ring.birth) / 1000;
      const t = clamp(age / ring.duration, 0, 1);
      const scale = 1 + t * ring.maxRadius * 15;
      ring.mesh.scale.set(scale, scale, 1);
      ring.mesh.material.opacity = 1 - t;
      ring.mesh.material.emissiveIntensity = 3 * (1 - t);
      if (t >= 1) {
        this.scene.remove(ring.mesh);
        ring.mesh.geometry.dispose();
        ring.mesh.material.dispose();
        this.rings.splice(i, 1);
      }
    }
  }

  clear() {
    for (const ring of this.rings) {
      if (!ring.disposed) {
        this.scene.remove(ring.mesh);
        ring.mesh.geometry.dispose();
        ring.mesh.material.dispose();
        ring.disposed = true;
      }
    }
    this.rings.length = 0;
  }
}

import * as THREE from 'three';
import { clamp } from 'shared/math/MathUtils.js';
import { MemoryTracker } from 'shared/memory/MemoryTracker.js';

const tracker = new MemoryTracker();

export class MotionTrails {
  constructor(scene) {
    this.scene = scene;
    this.trails = new Map(); // mesh.uuid -> trail data
  }

  attach(mesh, length = 8, color = 0x00ffff, lineWidth = 2) {
    const uuid = mesh.uuid;
    if (this.trails.has(uuid)) return;

    const positions = new Float32Array(length * 3);
    const colors = new Float32Array(length * 3);
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    tracker.trackGeometry(geometry);

    const c = new THREE.Color(color);
    const material = new THREE.LineBasicMaterial({
      vertexColors: true,
      transparent: true,
      linewidth: lineWidth,
      depthWrite: false,
    });
    tracker.trackMaterial(material);

    const line = new THREE.Line(geometry, material);
    line.frustumCulled = false;
    this.scene.add(line);

    const history = [];
    for (let i = 0; i < length; i++) {
      history.push(new THREE.Vector3());
    }

    this.trails.set(uuid, { line, geometry, material, history, length, color: c, visible: false });
  }

  detach(mesh) {
    const uuid = mesh.uuid;
    const data = this.trails.get(uuid);
    if (!data) return;
    this.scene.remove(data.line);
    data.geometry.dispose();
    data.material.dispose();
    this.trails.delete(uuid);
  }

  update(dt) {
    for (const [uuid, data] of this.trails) {
      const mesh = this.scene.getObjectByProperty('uuid', uuid);
      if (!mesh || !mesh.visible) {
        data.visible = false;
        data.line.visible = false;
        continue;
      }

      data.visible = true;
      data.line.visible = true;

      // Shift history
      for (let i = data.history.length - 1; i > 0; i--) {
        data.history[i].copy(data.history[i - 1]);
      }
      mesh.getWorldPosition(data.history[0]);

      const posAttr = data.geometry.getAttribute('position');
      const colAttr = data.geometry.getAttribute('color');

      for (let i = 0; i < data.length; i++) {
        const p = data.history[i];
        posAttr.setXYZ(i, p.x, p.y, p.z);

        const alpha = 1.0 - (i / data.length);
        colAttr.setXYZ(i, data.color.r, data.color.g, data.color.b);
      }

      posAttr.needsUpdate = true;
      colAttr.needsUpdate = true;
    }
  }

  clear() {
    for (const [uuid, data] of this.trails) {
      this.scene.remove(data.line);
      data.geometry.dispose();
      data.material.dispose();
    }
    this.trails.clear();
  }
}

import { Shield } from './Shield.js';
import { CONFIG } from './config.js';

const SHIELD_POSITIONS = [
  { x: -4.5, y: -2.5 },
  { x: -1.5, y: -2.5 },
  { x:  1.5, y: -2.5 },
  { x:  4.5, y: -2.5 },
];

export class Shields {
  constructor(scene, tracker) {
    this.scene = scene;
    this.tracker = tracker;
    this.shields = [];
  }

  init() {
    this._createAll();
  }

  _createAll() {
    for (const s of this.shields) s.dispose();
    this.shields = [];
    for (const pos of SHIELD_POSITIONS) {
      this.shields.push(new Shield(this.scene, this.tracker, pos.x, pos.y));
    }
  }

  erode(point, radius) {
    for (const shield of this.shields) {
      if (shield.isAlive()) {
        shield.erode(point.x, point.y, radius);
      }
    }
  }

  reset() {
    this._createAll();
  }

  dispose() {
    for (const shield of this.shields) shield.dispose();
    this.shields = [];
  }
}

